INSERT INTO `liste_des_jardins_remarquables` (`Nom du jardin`, `Code Postal`, `Region`, `Departement`, `Adresse complete`, `Adresse de l’entree du public`, `Numero et libelle de la voie`, `Complement d'adresse`, `Commune`, `Code INSEE`, `Code INSEE Departement`, `Code INSEE Region`, `Latitude`, `Longitude`, `Site Internet et autres liens`, `Types`, `Annee d'obtention`, `Description`, `Auteur / Nom de l'illustre`, `Identifiant DEPS`, `Identifiant origine`, `Accessible au public`, `Conditions d’ouverture`, `Equipement Précision`, `Date de création`, `Date de MAJ`, `coordonnees_geographiques`) VALUES
('Parc du domaine de Nacqueville', 50690, 'Normandie', 'Manche', '1B Rte de la Castellerie, 50690 La Hague, France', '1B Rte de la Castellerie, 50690 La Hague, France', '1B Rte de la Castellerie', '', 'La Hague', '50041', '50', 28.0, 49.609150000000, -1.6924720000000, '[\"http://www.nacqueville.com\"]', 'Parc paysager,Jardin privé', 2004, 'Château du XVIe siècle situé dans un parc à l\'anglaise romantique créé en 1830 traversé par une rivière en cascade bordée d\'arums et animé par une pièce d\'eau et des fontaines fleuries. Vue merveilleuse sur la mer.', '', 'JARD_50041_0002', 'MHR_28_JR0015', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-07-22 10:28:16', '49.60915, -1.692472'),
('Parc du château de Thorigny', 89260, 'Bourgogne-Franche-Comté', 'Yonne', '3 Rue de la Division Leclerc, 89260 Thorigny-sur-Oreuse, France', '3 Rue de la Division Leclerc, 89260 Thorigny-sur-Oreuse, France', '3 Rue de la Division Leclerc', '', 'Thorigny-sur-Oreuse', '89414', '89', 27.0, 48.294482000000, 3.3982900000000, '[\"http://www.amisdethorigny.com\"]', 'Jardin régulier,Jardin privé', 2006, 'Ce jardin aménagé par André Le Nôtre au XVIIe siècle a été remodelé par Pierre Carlier après 1843. Ses descendants, au fil du temps, ont mis en valeur le parc. Le jardin présente des éléments remarquables : pont, cascade, cours d\'eau, plan d\'eau et des éléments végétaux : arbres d\'alignement (tilleuls)...', '', 'JARD_89414_0001', 'MHR_27_JR0016', '[]', '[]', 'monument historique', '2020-12-11 13:14:55', '2022-07-22 10:28:04', '48.294482, 3.39829'),
('Jardin des Géants', 59110, 'Hauts-de-France', 'Nord', '1 Rue de la Communauté, 59110 La Madeleine, France', '1 Rue de la Communauté, 59110 La Madeleine, France', '1 Rue de la Communauté', '', 'La Madeleine', '59368', '59', 32.0, 50.643433300000, 3.0754808000000, '[\"https://www.lilletourism.com/parc-et-jardin-lille/jardin-des-geants.html\"]', 'Jardin contemporain,Jardin public', 2020, 'Le jardin des Géants, à proximité de la gare Lille Europe, s\'étend sur plus de 2 hectares. En lieu et place d\'un ancien parking aérien aujourd\'hui enterré, les paysagistes de l\'Atelier Mutabilis ont créé un nouvel espace de nature et de poésie, inauguré en juillet 2009. On y accède par le Parvis des Nuages, planté de 5 espèces de bambous puis par l\'Herbe des Géants, où alternent clairières et végétation luxuriante. Les végétaux sont « maîtres » des lieux, avec plus de 45 000 plantes. Le Jardin des Sources offre une déambulation paisible entre bassins et miroirs d\'eau et architectures d’osier tressé, avec en toile de fond, les tours futuristes d\'Euralille. Havre de paix au cœur de la ville, l\'atmosphère qui y règne résulte d\'une alchimie dont les composantes sont liées aux cinq sens. \r\n Le Jardin des Géants a été conçu comme un lieu de vie, de culture et de diversité grâce à ses espaces ouverts et une grande esplanade dédiée aux réceptions et aux spectacles.', '', '', 'MHR_32_JR0032', '[]', '[]', '', '2022-08-18 15:24:24', '2022-09-13 17:01:10', '50.6434333, 3.0754808'),
('Jardin de l\'horticulture', 51200, 'Grand Est', 'Marne', '36 Rue Comte de Lambertye, 51200 Épernay, France', '36 Rue Comte de Lambertye, 51200 Épernay, France', '36 Rue Comte de Lambertye', '', 'Épernay', '51230', '51', 44.0, 49.033336000000, 3.9507310000000, '[\"http://www.epernay.fr\"]', 'Parc paysager,Jardin public', 2012, 'Créé à partir de 1910 sur les plans de J.B. Thomereau, paysagiste, le parc met en scène de nombreuses essences rares parmi lesquelles un fau de Verzy, un hêtre à feuilles de fougère, un hêtre marginé de rose, un muscadier, un cyprès chauve, …. Cette collection est complétée d’une roseraie et d’un verger-école toujours gérés par la Société d’horticulture et de viticulture d’Épernay.', '', 'JARD_51230_0001', 'MHR_44_JR0027', '[]', '[]', '', '2020-12-11 13:14:28', '2022-07-22 10:28:11', '49.033336, 3.950731'),
('Jardin d’Angélique', 76520, 'Normandie', 'Seine-Maritime', '1750 Rte de Lyons, 76520 Montmain, France', '1750 Rte de Lyons, 76520 Montmain, France', '1750 Rte de Lyons', '', 'Montmain', '76448', '76', 28.0, 49.410691000000, 1.2495500000000, '[\"http://www.montmain.fr/commune/patrimoine\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2015, 'Créés il y a 18 ans par Yves et Gloria Le Bellegard à la mémoire de leur fille Angélique,\r\n ces jardins sont divisés en 2 parties:\r\n - Au sud du manoir du XVIIe siècle, un jardin aux allées rectilignes, aux haies taillées au cordo...\r\n - Au nord, mélange de nature plus sauvage et infinité d\'espèces de fleurs et d\'arbres.\r\n Un petit cours d\'eau artificiel et de jolis petits bassins agrémentent le tout et donne une âme à l\'ensemble.\r\n Au milieu de votre flânerie vous pourrez vous reposer quelques instants sur un banc où sous une tonnelle.', '', 'JARD_76448_0001', 'MHR_28_JR0039', '[]', '[]', '', '', '2022-07-22 10:28:54', '49.410691, 1.24955'),
('Domaine de Charance', 5000, 'Provence-Alpes-Côte d\'Azur', 'Hautes-Alpes', '14 Av. de Charance, 05000 Gap, France', '14 Av. de Charance, 05000 Gap, France', '14 Av. de Charance', '', 'Gap', '5061', '5', 93.0, 44.563106000000, 6.0630430000000, '[\"https://www.gap-tallard-vallees.fr/fr/decouvrir/nature-et-decouvertes/parcs-et-domaines/domaine-de-charance/\"]', 'Jardin régulier,Jardin public', 2005, 'Domaine de 220 hectares avec jardins d’inspiration anglaise, italienne ou française. Collections de roses anciennes, plantes ornementales et alpines. \r\n Ouvert : de mi-avril à fin mai, septembre, octobre de 14h à 17h et de juin à août de 10h à 18h30 (fermé le mardi).', '', 'JARD_05061_0001', 'MHR_93_JR0022', '[]', '[]', 'monument historique', '', '2022-07-22 10:28:10', '44.563106, 6.063043'),
('Jardin des carrières de Saint-Adrien', 34290, 'Occitanie', 'Hérault', '72T Grand Rue, 34290 Servian, France', '72T Grand Rue, 34290 Servian, France', '72T Grand Rue', '', 'Servian', '34300', '34', 76.0, 43.425457000000, 3.3052630000000, '[\"http://www.stadrien.paysdepezenas.com\", \"https://www.facebook.com/LeJardinDeSaintAdrien\"]', 'Parc paysager,Jardin privé', 2004, 'Le jardin de Saint Adrien fait partie des sites les plus spectaculaires de notre région : d’anciennes carrières datant du Moyen-âge ont été transformées peu à peu en bassins avec écrin de verdure, paradoxale oasis posée sur les roches volcaniques. Quatre plans d\'eau apportent la fraîcheur dans ce paysage minéral tandis que les plantations et les fleurs en font une halte estivale sous le signe de la magie et de la sérénité.', '', 'JARD_34300_0001', 'MHR_76_JR0012', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:45', '43.425457, 3.305263'),
('Parc botanique de Cornouaille', 29120, 'Bretagne', 'Finistère', '368 Rte de Pont l\'Abbé, 29120 Combrit, France', '368 Rte de Pont l\'Abbé, 29120 Combrit, France', '368 Rte de Pont l\'Abbé', '', 'Combrit', '29037', '29', 53.0, 47.883534000000, -4.1649490000000, '[\"http://www.parcbotanique.com\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2005, 'Parc privé aménagé à l\'anglaise, qui abrite une très riche collection de plantes de l\'Ouest et du monde entier (Amérique du Sud et du Nord, Afrique du Sud, Australie, Nouvelle-Zélande, Chine, Japon, Laponie, etc.), un vaste jardin aquatique et une collection de minéraux du Massif armoricain et du monde entier (4,5 ha).', '', 'JARD_29037_0001', 'MHR_53_JR0010', '[]', '[]', '', '2020-06-08 09:24:00', '2022-10-07 22:15:25', '47.883534, -4.164949'),
('Roseraie David Austin', 60127, 'Hauts-de-France', 'Oise', '11 Rue des Lombards, 60127 Morienval, France', '11 Rue des Lombards, 60127 Morienval, France', '11 Rue des Lombards', '', 'Morienval', '60260', '60', 32.0, 49.296817500000, 2.9226608000000, '[\"http://www.abbayedemorienval.com\", \"https://fr-fr.facebook.com/abbayemorienval\"]', 'Jardin régulier,Jardin contemporain,Jardin de collection,Jardin privé', 2020, 'L’architecte des lieux, grand aïeul du propriétaire actuel, s’est inspiré de la mémoire contemplative du site, celui de l’abbaye de Morienval, pour y recréer un cadre qui serait conforme selon lui au « génie » du lieu, celui d’un paysage naturel idéal. Le 27 mai 2014, l’Abbaye de Morienval a ouvert au public la première roseraie officielle David Austin en France. Dédiée au répertoire floral de David Austin avec 1600 rosiers et 154 variétés, répartis en 300 massifs et 14 lits de 30 m de long chacun, cette roseraie classique, structurée par des arches métalliques, a été créée en 2011 et dessinée par Michael Marriott, directeur artistique de David Austin Roses, au chevet de l’église abbatiale du 12e siècle. Parallèlement, le jardin est aussi un « Rose Center » où le visiteur peut acquérir les rosiers David Austin, qu’il a découverts lors de la visite.', '', '', '', '[]', '[]', '', '2022-09-13 17:09:04', '2022-09-13 17:09:04', '49.2968175, 2.9226608'),
('Jardin arboretum de la Sédelle', 23160, 'Nouvelle-Aquitaine', 'Creuse', '1 Villejoint, 23160 Crozant, France', '1 Villejoint, 23160 Crozant, France', '1 Villejoint', '', 'Crozant', '23070', '23', 75.0, 46.361436000000, 1.6072920000000, '[\"http://www.arboretumsedelle.com\", \"https://www.facebook.com/ArboretumSedelle\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2020, 'La relation toute en douceur des jardins successifs, de cette vallée descendante vers la Sedelle, avec les différents milieux naturels en fait un exemple unique contemporain de paysage jardiné.\r\n  La réutilisation des plantes locales est le facteur dominant', '', 'JARD_23070_0001', 'MHR_75_JR0061', '[]', '[]', '', '2022-03-09 12:54:19', '2022-07-22 10:28:06', '46.361436, 1.607292'),
('Jardin des herbes', 26700, 'Auvergne-Rhône-Alpes', 'Drôme', '140 Les Escrottes, 26700 La Garde-Adhémar, France', '140 Les Escrottes, 26700 La Garde-Adhémar, France', '140 Les Escrottes', '', 'La Garde-Adhémar', '26138', '26', 84.0, 44.390508000000, 4.7508330000000, '[\"http://www.la-garde-adhemar.com\"]', 'Jardin contemporain,Jardin de collection,Jardin vivrier,Jardin public', 2006, 'Créé en 1990 par Danielle Arcucci, ce jardin public contemporain de 3000 m² domine la vallée du Rhône. Regroupées par forme, couleur et vertus médicinales, 200 herbes ornent les terrasses selon différents dessins géométriques, passages ombrés, cascade, et parterre en forme de soleil. Ouvert toute l\'année et sur RV pour les VG.', '', 'JARD_26138_0001', 'MHR_84_JR0020', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:27:49', '44.390508, 4.750833'),
('Jardin de l’Ancienne abbaye Saint-André', 30400, 'Occitanie', 'Gard', '31 Rue Mnt du Fort, 30400 Villeneuve-lès-Avignon, France', '31 Rue Mnt du Fort, 30400 Villeneuve-lès-Avignon, France', '31 Rue Mnt du Fort', '', 'Villeneuve-lès-Avignon', '30351', '30', 76.0, 43.964398000000, 4.7989070000000, '[\"http://www.abbayesaintandre.fr\", \"https://www.facebook.com/abbayesaintandre/\", \"https://www.instagram.com/abbayesaintandre/\"]', 'Jardin régulier,Jardin privé', 2015, 'Située sur le mont Andaon, dans l’imposante enceinte du Fort Saint-André, l’abbaye bénédictine et royale domine le Rhône et fait face à la Cité des Papes située sur l’autre rive. Fondée au Xe siécle, son Palais Abbatial sera remanié par Mignard, architecte du roi Louis XIV, reflétant la magnificence et l’élégance du XVIIIe siécle. Les jardins en terrasses de style \"Renaissance toscane\" et Méditerranéen s’étalent entre les vestiges des églises romanes et des tombeaux du Haut Moyen Âge, laissant découvrir des parterres fleuris de rosiers anciens, des plantes méditerranéennes, ainsi que pins et oliviers centenaires. Les terrasses offrent un panorama exceptionnel sur le Palais des Papes, les Alpilles, le Luberon, le Ventoux et les Dentelles du Montmirail. Tout ici laisse deviner l’important passé de ce lieu puissant et harmonieux, tremplin de l’imaginaire.', '', 'JARD_30351_0001', 'MHR_76_JR0005', '[]', '[]', 'monument historique', '2020-12-11 13:15:01', '2022-12-07 17:42:15', '43.964398, 4.798907'),
('Jardins du château de Caudon', 24250, 'Nouvelle-Aquitaine', 'Dordogne', '28 La Tuilerie, 24250 Saint-Cybranet, France', '28 La Tuilerie, 24250 Saint-Cybranet, France', '28 La Tuilerie', '', 'Saint-Cybranet', '24152', '24', 75.0, 44.791704000000, 1.1604110000000, '[]', 'Parc paysager,Jardin contemporain,Jardin privé', 2007, 'Parc et jardin à l’anglaise avec chambres de buis. Château et chapelle monolithe (Monument historique).', '', 'JARD_24152_0001', 'MHR_75_JR0009', '[]', '[]', '', '', '2022-07-22 10:28:16', '44.791704, 1.160411'),
('Jardin des ifs', 60380, 'Hauts-de-France', 'Oise', '4 Rue Henri le Sidaner, 60380 Gerberoy, France', '4 Rue Henri le Sidaner, 60380 Gerberoy, France', '4 Rue Henri le Sidaner', '', 'Gerberoy', '60271', '60', 32.0, 49.533981000000, 1.8499160000000, '[\"http://www.lejardindesifs.com/\", \"https://www.facebook.com/lejardindesifs\"]', 'Jardin régulier,Jardin vivrier,Jardin privé', 2018, 'La propriété se compose d’une maison entre cour avec dépendances au Sud et jardin au Nord, datant de la première moitié du XVIIIe siècle. C’était la maison de Charles Levesque de La Roque, lieutenant général du vidamé de Gerberoy. \r\n Le jardin qui couvre environ 1600 m² est un jardin historique en terrasses planté d’ifs en topiaire pluri-séculaires. Il s\'agit d\'un jardin très vert, à l\'origine dénué de fleurs. Les rosiers ont été ajoutés par les propriétaires actuels pour donner de la couleur et de nouveaux parfums au jardin. Les buis les plus anciens sont les plus proches de la maison. Rotondiformes, ils ont entre 150 et 200 ans. L\'allée centrale du jardin prolonge le vestibule de la maison, et se déroule jusqu\'à un surprenant cabinet de verdure en if taillé, qui a obtenu le label \"Arbre remarquable de France\". En contrebas du cabinet de verdure et au pied d\'un escalier ancien, se trouve le potager.', '', 'JARD_60271_0002', 'MHR_32_JR0028', '[]', '[]', '', '2020-06-08 09:24:00', '2022-12-15 12:06:58', '49.533981, 1.849916'),
('Les jardins du château de Drée', 71800, 'Bourgogne-Franche-Comté', 'Saône-et-Loire', '623 À Gueurce, 71800 Curbigny, France', '623 À Gueurce, 71800 Curbigny, France', '623 À Gueurce', '', 'Curbigny', '71160', '71', 27.0, 46.302306000000, 4.2996760000000, '[\"http://www.chateau-de-dree.com\", \"https://www.facebook.com/chateaudedree/\", \"https://www.instagram.com/chateaudedree_officiel/\"]', 'Jardin régulier,Jardin privé', 2004, 'Monument historique privé, le Château de Drée ressuscite grâce au mobilier, aux jardins, l\'art de vivre au XVIIIe siècle. Visite d\'une quinzaine de pièces meublées dignes d\'une demeure princière : cuisine, chambre du roi, salons d\'apparats, chambres de maîtres, chapelle... Promenade libre des jardins et dépendances : colombier, prison, glacière, roseraie, salle des bains, broderie de buis, bassins et statues.', '', 'JARD_71160_0001', 'MHR_27_JR0013', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:03', '46.302306, 4.299676'),
('Jardin de la poterie Hillen', 65230, 'Occitanie', 'Hautes-Pyrénées', '1675 Rte de Lalanne, 65230 Thermes-Magnoac, France', '1675 Rte de Lalanne, 65230 Thermes-Magnoac, France', '1675 Rte de Lalanne', '', 'Thermes-Magnoac', '65442', '65', 76.0, 43.286741000000, 0.6106980000000, '[\"http://les-jardins-de-la-poterie-hillen.blogspot.com/\", \"https://www.facebook.com/lesjardinsdelapoterieHillen\"]', 'Parc paysager,Jardin contemporain,Jardin privé', 2009, 'Jardin privé de 5 hectares aménagé en 2004 sur plusieurs niveaux. Mosaïque de jardins thématiques : potager biologique, arbres et arbustes remarquables, collections de vivaces, bambous et graminées. Jardins intime, des cinq sens, gourmand à influence médiévale, exotique, du Nord, du Sud. Biotope lotus. Sept pièces d\'eau, lac, fontaine italienne, serre, sculptures.', '', 'JARD_65442_0001', 'MHR_76_JR0024', '[]', '[]', '', '2020-06-08 09:23:00', '2022-07-22 10:28:18', '43.286741, 0.610698'),
('Parc et jardin du château de Conteval', 62360, 'Hauts-de-France', 'Pas-de-Calais', '11 Rue de la Bergerie, 62360 La Capelle-lès-Boulogne, France', '11 Rue de la Bergerie, 62360 La Capelle-lès-Boulogne, France', '11 Rue de la Bergerie', '', 'La Capelle-lès-Boulogne', '62908', '62', 32.0, 50.733803000000, 1.7039820000000, '[]', 'Parc paysager,Jardin vivrier,Jardin privé', 2018, 'Parc créé à la fin du XVIIIe siècle sur une importante parcelle du domaine royal, aliéné par Louis XVI au profit des Frères Delporte sur le plan du Baron de Courset, auteur du \"Botaniste cultivateur\" paru en 1802 puis en 1811. Pionniers de l\'acclimatation des plantes exotiques et tenant du jardin naturaliste dit \"à l\'anglaise\", ils firent un parc très ouvert aux perspectives guidant la vue jusqu\'aux confins du Calaisis. Agrandi au XIXe siècle et aménagé par Eugène Houlet de Boulogne, disciple d\'Edouard André et jardinier du Baron de Rothschild au chateau de Laversine.', '', 'JARD_62908_0001', 'MHR_32_JR0031', '[]', '[]', 'monument historique', '', '2022-12-15 12:08:18', '50.733803, 1.703982'),
('Domaine national de Saint-Cloud', 92210, 'Île-de-France', 'Hauts-de-Seine', 'National Estate of Saint-Cloud, 1 Av. de la Grille d\'Honneur, 92210 Saint-Cloud, France', 'National Estate of Saint-Cloud, 1 Av. de la Grille d\'Honneur, 92210 Saint-Cloud, France', 'National Estate of Saint-Cloud', '', 'Saint-Cloud', '92064', '92', 11.0, 48.837733000000, 2.2167190000000, '[\"http://saint-cloud.monuments-nationaux.fr\", \"https://www.instagram.com/domainenationaldesaintcloud/\"]', 'Jardin régulier,Parc paysager,Jardin public', 2004, 'Jardin régulier et parc dessiné par André Le Nôtre (XVIIe siècle), jardin mixte dessiné par Pierre Contant d’Ivry (milieu XVIIIe siècle), jardin paysager par Maximilien-Joseph Hurtault (Jardin du Trocadéro 1823-1826), jardins ouvriers et ferme pédagogique (XXe siècle)', '', 'JARD_92064_0001', 'MHR_11_JR0009', '[]', '[]', 'monument historique', '2022-03-09 12:55:00', '2022-07-22 10:27:59', '48.837733, 2.216719'),
('Jardin des plantes', 34000, 'Occitanie', 'Hérault', '12 Bd Henri IV, 34000 Montpellier, France', '12 Bd Henri IV, 34000 Montpellier, France', '12 Boulevard Henri IV', '', 'Montpellier', '34172', '34', 76.0, 43.614280300000, 3.8732558000000, '[\"https://www.umontpellier.fr/patrimoine/jardin-des-plantes\", \"https://fr-fr.facebook.com/jdpmontpellier\"]', 'Jardin régulier,Jardin de collection,Jardin public', 2022, 'Fondé en 1593 par Henri IV, le plus ancien jardin botanique de France s’étend sur près de 5 hectares au cœur de Montpellier. Rattaché à la Faculté de médecine, cet espace autrefois entièrement dédié à la recherche et à l’enseignement continue d’attirer les chercheurs du monde entier. Le Jardin des Plantes de Montpellier est classé au titre des sites (12 février 1982) et protégé au titre des Monuments Historiques depuis le 3 septembre 1992.', '', '', '', '[]', '[]', '', '2022-09-15 15:42:59', '2022-09-15 15:42:59', '43.6142803, 3.8732558'),
('Jardin du Crapaud à trois pattes', 76270, 'Normandie', 'Seine-Maritime', '14 D97, 76270 Lucy, France', '14 D97, 76270 Lucy, France', '14 D97', '14 rue de la Houssaye-Béranger', 'Lucy', '76042', '76', 28.0, 49.782313900000, 1.4523432000000, '[\"https://lecrapaudatroispattes.jimdofree.com/le-jardin/\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2021, 'Le crapaud à trois pattes est un symbole Feng Shui incarnant la prospérité et la richesse. Le crapaud de ce jardin a pour seule et immense fortune, sa grande faculté à s\'émerveiller. Il vous étonnera quand, vous baguenauderez de chambre en chambre cernées de charmilles ondulantes, le long des parterres fleuris où se côtoient harmonieusement, arbres majestueux et petits buissons éclectiques parsemés de salades, coquelicots et choux. Vous irez de surprise en sourire. Ce n\'est pas le jardin d\'un jardinier mais celui d\'un sculpteur qui jardine pour son plaisir et le vôtre.', '', '', '', '[]', '[]', '', '2022-09-13 18:51:22', '2022-09-21 17:24:29', '49.7823139, 1.4523432'),
('Jardins de Marqueyssac', 24220, 'Nouvelle-Aquitaine', 'Dordogne', '152 Rue André Roque, 24220 Vezac, France', '152 Rue André Roque, 24220 Vezac, France', '152 Rue André Roque', '', 'Vezac', '24577', '24', 75.0, 44.835097000000, 1.1682110000000, '[\"http://www.marqueyssac.com\", \"https://www.facebook.com/marqueyssac/\", \"https://www.instagram.com/marqueyssac/\"]', 'Jardin privé', 2004, 'Les jardins romantiques et pittoresques de Marqueyssac offrent plus de 6 kilomètres de promenades ombragées, bordées de buis centenaires taillés, agrémentées de rocailles, théâtres de verdure.', '', 'JARD_24577_0001', 'MHR_75_JR0021', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:17', '44.835097, 1.168211'),
('Parc du château Gerbéviller', 54830, 'Grand Est', 'Meurthe-et-Moselle', '12 Rue de la Deuil, 54830 Gerbéviller, France', '12 Rue de la Deuil, 54830 Gerbéviller, France', '12 Rue de la Deuil', '', 'Gerbéviller', '54222', '54', 44.0, 48.493761000000, 6.5145230000000, '[\"http://www.chateau-gerbeviller.com/\"]', 'Parc paysager,Jardin vivrier,Jardin privé', 2004, 'Parc de 23 hectares, il est parcouru dans toute sa longueur par la Mortagne. Il a été dessiné par l\'architecte Berthault, paysagiste de Napoléon Ier, en 1820. Type même des jardins agrandis à l\'échelle du paysage, il offre une ample composition en « Y » comme les affectionnait Claude Gellée dit Le Lorrain. Un rare nymphée du XVIIe siècle et le \"Pavillon rouge\" dessinés probablement par Clément II Métezeau, vers 1620, constituent d’étonnantes fabriques précédées d’essences remarquables.', '', 'JARD_54222_0001', 'MHR_44_JR0033', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-07-22 10:28:12', '48.493761, 6.514523'),
('Jardin du Palais de la Berbie', 81000, 'Occitanie', 'Tarn', '16 Av. du Parc, 81000 Albi, France', '16 Av. du Parc, 81000 Albi, France', '16 Av. du Parc', '', 'Albi', '81004', '81', 76.0, 43.922817000000, 2.1452090000000, '[\"http://www.mairie-albi.fr\"]', 'Jardin régulier,Jardin public', 2009, 'Situé dans l\'enceinte du musée Toulouse-Lautrec, au cœur de la cité épiscopale d\'Albi, classée au patrimoine de l\'Unesco depuis 2010, le jardin public à la française date du XVIIe siècle. Il est surplombé par un chemin de ronde offrant une vue exceptionnelle sur le Tarn.', '', 'JARD_81004_0002', 'MHR_76_JR0027', '[]', '[]', 'monument historique; musee de france; patrimoine mondial de lunesco', '2020-12-11 13:14:09', '2022-07-22 10:28:18', '43.922817, 2.145209'),
('Jardin de Mireille', 47120, 'Nouvelle-Aquitaine', 'Lot-et-Garonne', '530 Chem. de la Gare, 47120 Auriac-sur-Dropt, France', '530 Chem. de la Gare, 47120 Auriac-sur-Dropt, France', '530 Chem. de la Gare', '', 'Auriac-sur-Dropt', '47018', '47', 75.0, 44.645015000000, 0.2432470000000, '[\"https://jardin-de-mireille.jimdofree.com/\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2020, 'Une passionnée de roses anciennes vous accueille dans son jardin où vous pourrez admirer plus de trois cent rosiers anciens, anglais, multiflora, mélangés à un grand nombre de vivaces, iris, hémérocalles, geraniums etc...ainsi que des arbres et arbustes rares. divers seringats, lilas en été les hortentias présentent une belle floraison. Le jardin est un aménagement de massifs mis en valeur par de grands passages engazonnés. Des pergolas où s\'entrelacent roses et clématites, autour d\'une ancienne ferme.', '', 'JARD_47018_0001', 'MHR_75_JR0063', '[\"ouvert\"]', '[\"de jour\"]', '', '2022-03-09 12:54:34', '2022-12-20 18:16:51', '44.645015, 0.243247'),
('Arboretum Al Gaulhia', 19140, 'Nouvelle-Aquitaine', 'Corrèze', '90 Rte du Vieux Ceyrat, 19140 Espartignac, France', '90 Rte du Vieux Ceyrat, 19140 Espartignac, France', '90 Rte du Vieux Ceyrat', '', 'Espartignac', '19076', '19', 75.0, 45.394176000000, 1.5918230000000, '[\"https://www.arboretum-algaulhia.net/\", \"https://www.facebook.com/Arboretum-Al-Gaulhia-Espartignac-111578955592602\"]', 'Jardin de collection,Jardin privé', 2017, 'Situé à quelques minutes d\'Uzerche, l\'arboretum Al Gaulhia est un parc paysager d\'environ 10 hectares. La grande variété d\'arbres et d’arbustes cohabite avec les nombreux espaces aquatiques et forme un univers riche en biodiversité agréable à visiter. L\'eau est ici omniprésente, le nom \"Al Gaulhia\" viendrait d\'ailleurs d\'un mot celte désignant une zone humide. Emblème du site, la dizaine d\'espèces de lotus offre en spectacle ses grandes feuilles et ses charmantes fleurs aux teintes roses ou blanches. Une collection de 80 espèces de bambous et 600 espèces d\'arbres et arbustes du monde entier complètent le tableau paysager, en trouvant leur place aux côtés de quelques arbres remarquables parfois tricentenaires.', '', 'JARD_19076_0001', 'MHR_75_JR0049', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-08 09:24:00', '2022-12-20 17:43:32', '45.394176, 1.591823'),
('Jardin des plantes Les Capellans', 66750, 'Occitanie', 'Pyrénées-Orientales', 'Mas des Capellans, 66750 Saint-Cyprien, France', 'Mas des Capellans, 66750 Saint-Cyprien, France', 'Mas des Capellans', 'rue Verdi', 'Saint-Cyprien', '66171', '66', 76.0, 42.605299500000, 3.0302023000000, '[\"https://www.tourisme-saint-cyprien.com/les-incontournables/le-jardin-des-plantes\"]', 'Parc paysager,Jardin de collection,Jardin public', 2022, 'Le parc, de 5 ha environ, a été restauré par la ville de Saint-Cyprien en 1998, pour sauvegarder ce patrimoine hérité du XIXe siècle et en faire un jardin botanique comptant plus de 800 espèces dont 35 de palmiers, une bambouseraie, une collection remarquable de roses anciennes et des essences méditerranéennes parfois très rares. Un long « embarcadère » conduit les promeneurs jusqu\'au plan d\'eau sur lequel règne, l\'été, le nénuphar géant Victoria.', '', '', '', '[]', '[]', '', '2022-09-15 15:29:23', '2022-09-15 15:33:15', '42.6052995, 3.0302023'),
('Jardin zoologique tropical', 83250, 'Provence-Alpes-Côte d\'Azur', 'Var', 'Route de Valcros 83250 La Londe-les-Maures', 'Route de Valcros, 83250 La Londe-les-Maures, France', 'Route de Valcros', '', 'La Londe-les-Maures', '83071', '83', 93.0, 43.155665000000, 6.2557060000000, '[\"http://www.zootropical.com\"]', 'Jardin de collection,Jardin privé', 2008, 'Jardin-conservatoire zoologique et botanique. Acclimatation, arboretum, collections (oiseaux,primates, plantes exotiques), reproduction d’espèces en voie d’extinction.', '', 'JARD_83071_0001', 'MHR_93_JR0029', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-08 09:23:00', '2022-12-21 12:49:39', '43.155665, 6.255706'),
('Jardins du château de Viels-Maisons', 2540, 'Hauts-de-France', 'Aisne', '11 Pl. du Marché, 02540 Viels-Maisons, France', '11 Pl. du Marché, 02540 Viels-Maisons, France', '11 Pl. du Marché', '', 'Viels-Maisons', '2798', '2', 32.0, 48.895492000000, 3.3969020000000, '[\"http://jardins-vielsmaisons.net\"]', 'Jardin régulier,Parc paysager,Jardin contemporain,Jardin vivrier,Jardin privé', 2004, 'Au chevet d\'une vieille église, entourée d\'un parc du XVIIe siècle (ISMH) et d\'un château du début du XIXe siècle, une succession de jardins dessinés par la paysagiste Sonja Gauron : un jardin de curé, de roses et de plantes officinales, un jardin anglais, camaïeu de couleurs, puis un jardin blanc, un jardin romantique, un jardin d\'eau, un jardin sauvage des hydrangeas, des rhododendrons et un cadran solaire analemmatique.', '', 'JARD_02798_0001', 'MHR_32_JR0012', '[\"ouvert\"]', '[\"de jour\"]', 'monument historique', '2020-12-11 13:16:00', '2022-12-15 15:41:16', '48.895492, 3.396902'),
('Parc et jardin du château de Rosanbo', 22420, 'Bretagne', 'Côtes d\'Armor', '4 Château de Rosanbo, 22420 Lanvellec, France', '4 Château de Rosanbo, 22420 Lanvellec, France', '4 Château de Rosanbo', '', 'Lanvellec', '22119', '22', 53.0, 48.625773000000, -3.5528150000000, '[\"http://www.rosanbo.net\", \"https://www.facebook.com/chateau.derosanbo\"]', 'Jardin régulier,Jardin privé', 2012, 'Un jardin classique est créé à la fin du 17e siècle lors du réaménagement d’un château construit vers 1500 dans un site dominant la vallée du Bô. Au tournant des 19e et 20e siècles, un parc néoclassique conçu par les paysagistes Henri et Achille Duchêne vient compléter ce jardin : clos de murs, ce parc destiné à la pratique équestre et à la promenade méditative comprend allées cavalières, manège et piste de galop, salles de verdure, tapis vert et charmille voûtée longue de 400 mètres (MH – 5 ha).', '', 'JARD_22119_0001', 'MHR_53_JR0002', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-10-07 22:06:36', '48.625773, -3.552815'),
('Jardins de l’Horticulture et de la Patte d’Oie, dit \"Parc Schneiter\"', 51100, 'Grand Est', 'Marne', '12 Bd Louis Roederer, 51100 Reims, France', '12 Bd Louis Roederer, 51100 Reims, France', '12 Bd Louis Roederer', '', 'Reims', '51454', '51', 44.0, 49.256897000000, 4.0227960000000, '[\"http://www.reims.fr\"]', 'Jardin public', 2015, 'Deux importants paysagistes sont intervenus dans la conception de ce jardin, créé par la société d’Horticulture de Reims : Édouard Redont a dessiné la partie pittoresque en 1895 et Jean-Claude Nicolas Forestier a conçu la roseraie en 1924.', '', 'JARD_51454_0001', 'MHR_44_JR0030', '[]', '[]', '', '2020-12-11 13:14:18', '2022-07-22 10:28:12', '49.256897, 4.022796'),
('Parc Gonzalez', 83230, 'Provence-Alpes-Côte d\'Azur', 'Var', '1594 Bd du Soleil, 83230 Bormes-les-Mimosas, France', '1594 Bd du Soleil, 83230 Bormes-les-Mimosas, France', '1594 Bd du Soleil', '', 'Bormes-les-Mimosas', '83019', '83', 93.0, 43.147361000000, 6.3410050000000, '[\"https://www.bormeslesmimosas.com/fr/quoi-faire/visites-et-patrimoine/les-jardins\"]', 'Jardin contemporain,Jardin de collection,Jardin public', 2015, 'Ce parc unique en Europe, véritable joyau en plein coeur du village, est composé de plus de 500 espèces de végétaux australiens. Il a vu le jour grâce à la générosité de Vivianne Grimminger et Carmen Martinez. Toutes deux ont ainsi souhaité offrir ce terrain d’une superficie de 3000 m2 afin de sceller leur histoire et celle de la famille Gonzalez à la ville de Bormes les Mimosas, si chère à Roberta Gonzalez, fille du sculpteur Julio Gonzalez. Un geste généreux qui aura permis, en 2002, au Parc Gonzalez, de se concrétiser sous l’impulsion de Gilles Augias, aujourd’hui responsable du Service Espaces Vert de la ville et de Gérard Cavatore, le spécialiste du mimosa.', '', 'JARD_83019_0001', 'MHR_93_JR0035', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:11', '43.147361, 6.341005'),
('Village-jardin de Chédigny', 37310, 'Centre-Val de Loire', 'Indre-et-Loire', '226 La Villetrie, 37310 Chédigny, France', '226 La Villetrie, 37310 Chédigny, France', '226 La Villetrie', '', 'Chédigny', '37066', '37', 24.0, 47.210207000000, 0.9863520000000, '[\"http://rosesdechedigny.canalblog.com\", \"https://www.facebook.com/chedignyjardin\"]', 'Jardin de collection,Jardin public', 2013, 'Venez découvrir ce village exceptionnel où les rosiers et les vivaces ont envahi les rues pour le plus grand plaisir de ses habitants et des visiteurs.', '', 'JARD_37066_0001', 'MHR_24_JR0013', '[]', '[]', '', '', '2022-07-22 10:27:57', '47.210207, 0.986352'),
('Jardin de la bastide de Romégas', 13540, 'Provence-Alpes-Côte d\'Azur', 'Bouches-du-Rhône', '2721 Chem. de St Donat, 13540 Aix-en-Provence, France', '2721 Chem. de St Donat, 13540 Aix-en-Provence, France', '2721 Chem. de St Donat', '', 'Aix-en-Provence', '13001', '13', 93.0, 43.562039000000, 5.4496380000000, '[\"https://www.jardins-romegas-provence.com\"]', 'Jardin régulier,Jardin privé', 2011, 'Jardins à la française et à l’anglaise au pied d’une bastide XVIIIe siècle, face à Sainte-Victoire. Chapelle, bassins, tèse, aire de battage, fontaine et bassins, volière, labyrinthes.', '', 'JARD_13001_0001', 'MHR_93_JR0017', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:20', '43.562039, 5.449638'),
('Jardins du château de la Ballue', 35560, 'Bretagne', 'Ille-et-Vilaine', '1 Bois de la Ballue 35560 Bazouges-la-Pérouse', '1 Bois de la Ballue 35560 Bazouges-la-Pérouse', '1 Bois de la Ballue', '', 'Bazouges-la-Pérouse', '35004', '35', 53.0, 48.438444000000, -1.5471930000000, '[\"http://www.laballuejardin.com\", \"https://www.facebook.com/LaBalluesonchateauetsesjardins\", \"https://twitter.com/LaBallue\", \"https://www.instagram.com/chateaudelaballue/\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2005, 'Deux jardins d’architectes dessinés dans les années 1970 composent l’espace autour d’un château Louis XIII : un jardin « classique » conçu par François-Hébert Stevens selon le modèle italien des premiers jardins de cloître, et un jardin maniériste créé par Paul Maymont, déambulation intimiste dans treize chambres de verdure. Art topiaire et sculptures contemporaines se conjuguent avec harmonie et raffinement. Importante collection de buis (MH – 1,5 ha).', '', 'JARD_35019_0001', 'MHR_53_JR0016', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-11-25 15:57:25', '48.438444, -1.547193'),
('Parc du château de Trévarez', 29520, 'Bretagne', 'Finistère', 'Trevarez, 29520 Saint-Goazec, France', 'Trevarez, 29520 Saint-Goazec, France', 'Trevarez', '', 'Saint-Goazec', '29027', '29', 53.0, 48.156504600000, -3.8076412000000, '[\"http://www.cdp29.fr/fr/presentation-trevarez\", \"https://www.facebook.com/cheminsdupatrimoineenfinistere\"]', 'Jardin régulier,Parc paysager,Jardin contemporain,Jardin de collection,Jardin public', 2006, 'Vaste domaine départemental aménagé sur le site d\'un château de la fin du 19e siècle, comprenant parc à l\'anglaise, jardin régulier, jardin italien, jardin romantique... Collections de référence de rhododendrons ainsi que de camélias et d\'hydrangeas. Chaque saison, des installations éphémères d\'artistes internationaux offrent une découverte renouvelée du domaine (MH – 85 ha).\r\n  Cette année à Trévarez : Shigeko Hirakawa, François Méchain, Bob Verschueren et exposition photographique de Jacques Henri Lartigue.', '', 'JARD_29249_0001', 'MHR_53_JR0015', '[\"ouvert\"]', '[\"de jour\"]', 'monument historique; architecture contemporaine remarquable', '', '2022-12-16 16:12:15', '48.1565046, -3.8076412'),
('Les jardins du Logis de Forge', 16440, 'Nouvelle-Aquitaine', 'Charente', 'Forge 16440 Mouthiers-sur-Boëme', 'Forge 16440 Mouthiers-sur-Boëme', 'Forge', '', 'Mouthiers-sur-Boëme', '16101', '16', 75.0, 45.550843000000, 0.1281800000000, '[\"http://www.jardinsdulogisdeforge.com\"]', 'Parc paysager,Jardin contemporain,Jardin privé', 2004, 'Ces jardins contemporains sont l’œuvre de propriétaires passionnés qui ont laissé libre cours à leur imagination à partir de bâtiments anciens (XVIe et XVIIIe siècles). Ils s\'étirent avec élégance autour d\'un étang formé par une importante résurgence. À l\'art des jardins japonais correspond le reflet de la colline dans l\'eau où l\'on contemple les nénuphars depuis la tonnelle. Perspectives, décors, échappées, contribuent à surprendre le promeneur qui découvre la roue du moulin ou encore des nymphes de bronze sortant de coquillages d\'où jaillissent des jets d\'eau.', '', 'JARD_16236_0001', 'MHR_75_JR0037', '[]', '[]', '', '2020-06-08 09:24:00', '2022-11-27 12:04:18', '45.550843, 0.12818'),
('Jardin du château de Pange', 57530, 'Grand Est', 'Moselle', '9 Rue des Tilleuls, 57530 Pange, France', '9 Rue des Tilleuls, 57530 Pange, France', '9 Rue des Tilleuls', '', 'Pange', '57533', '57', 44.0, 49.085555000000, 6.3542670000000, '[\"http://www.chateaudepange.fr\"]', 'Jardin contemporain,Jardin privé', 2004, '\"Jardin dans la campagne et campagne dans le jardin\", Pange est une ode à la nature. Conçu par le paysagiste Louis Benech, ce jardin résolument contemporain et champêtre s\'intègre à merveille dans la splendide campagne environnante.', '', 'JARD_57533_0001', 'MHR_44_JR0042', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:35', '49.085555, 6.354267'),
('Domaine de Poulaines', 36210, 'Centre-Val de Loire', 'Indre', '8 Rue du Château, 36210 Poulaines, France', '8 Rue du Château, 36210 Poulaines, France', '8 Rue du Château', '', 'Poulaines', '36162', '36', 24.0, 47.152390000000, 1.6648680000000, '[\"http://www.jardins.poulaines.com\", \"https://www.instagram.com/domainedepoulaines/\"]', 'Parc paysager,Jardin contemporain,Jardin privé', 2015, 'Réhabilitation autour de grands arbres et création avec Pierre et Marie-France Joyaux puis Claudie et Gérard Adeline\r\n Taille en nuage et jardin de bambous avec Christian Coureau (25 hectares dont 4,5 hectares)\r\n Gloriette, sculptures, pièce d\'eau, rivière...', '', 'JARD_36162_0001', 'MHR_24_JR0011', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:43', '47.15239, 1.664868'),
('Jardins du Sardy', 24230, 'Nouvelle-Aquitaine', 'Dordogne', '7 Rte de Sardy, 24230 Vélines, France', '7 Rte de Sardy, 24230 Vélines, France', '7 Rte de Sardy', '', 'Vélines', '24568', '24', 75.0, 44.858873000000, 0.1114570000000, '[\"http://jardinsdesardy.com\"]', 'Jardin privé', 2004, 'Jardins créés dans les années 1950 autour d\'une architecture ancienne. Inspiration italienne et anglaise dans une ambiance romantique ; jardin d’eau, rocailles, massifs de fleurs.', '', 'JARD_24568_0001', 'MHR_75_JR0020', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:17', '44.858873, 0.111457'),
('Jardins de Chaligny', 85320, 'Pays de la Loire', 'Vendée', '2 Rue Nicolas Boutaud, 85320 Sainte-Pexine, France', '2 Rue Nicolas Boutaud, 85320 Sainte-Pexine, France', '2 Rue Nicolas Boutaud', '', 'Sainte-Pexine', '85261', '85', 52.0, 46.547062000000, -1.1258150000000, '[\"http://www.jardindechaligny.wordpress.com\"]', 'Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2007, 'Entre bois et rivière, ces jardins réguliers reconduisent dans le paysage la structure géométrique d\'un authentique logis vendéen. Plusieurs espaces différenciés s\'y succèdent dans une unité remarquable, jardin fruitier, pergola, potager, orangerie, nymphée.', '', 'JARD_85261_0001', 'MHR_52_JR0017', '[]', '[]', 'monument historique', '2020-09-15 18:16:00', '2022-07-22 10:28:12', '46.547062, -1.125815'),
('Parc de Champagne', 51100, 'Grand Est', 'Marne', '10 Av. Henri Farman, 51100 Reims, France', '10 Av. Henri Farman, 51100 Reims, France', '10 Av. Henri Farman', '', 'Reims', '51454', '51', 44.0, 49.240740000000, 4.0558150000000, '[\"https://www.reims.fr/qualite-de-vie-environnement/reims-l-effervescence-cote-nature/les-grands-parcs/le-parc-de-champagne-4712.html\"]', 'Parc paysager,Jardin public', 2015, 'Melchior de Polignac, petit fils de la veuve Pommery, confie en 1907 au paysagiste rémois Édouard Redont, la création d’un parc arboré de 22 ha destiné au personnel de la célèbre maison de champagne. Le parc est ouvert depuis 3 ans, lorsqu’en 1913, Georges Hébert, fondateur d’une méthode « naturelle » pour former des sportifs, y installe le premier Collège d’Athlètes. Détruit par la guerre, le site sera restauré en 1922. Rebaptisés Parc de Champagne en 2004, les lieux sont aujourd’hui gérés par la ville de Reims.', '', 'JARD_51454_0002', 'MHR_44_JR0029', '[]', '[]', 'monument historique; patrimoine mondial de lunesco', '2020-12-11 13:16:43', '2022-07-22 10:28:12', '49.24074, 4.055815'),
('Herbarium des remparts', 80230, 'Hauts-de-France', 'Somme', 'Herbarium des Remparts, 36 Rue Brandt, 80230 Saint-Valery-sur-Somme, France', 'Herbarium des Remparts, 36 Rue Brandt, 80230 Saint-Valery-sur-Somme, France', 'Herbarium des Remparts', '', 'Saint-Valery-sur-Somme', '80721', '80', 32.0, 50.187362000000, 1.6288530000000, '[]', 'Jardin contemporain,Jardin vivrier,Jardin privé,Jardin public', 2004, 'L’Herbarium est un jardin public original de 1700 m². Niché sur les hauteurs de la cité médiévale, il se décline sur 4 terrasses et propose, autour d’un vieux pommier centenaire, des plantes aux multiples vertus (médicinales, aromatiques, textiles, tinctoriales, historiques…) ainsi qu’une diversité botanique des différents milieux naturels de la région.', '', 'JARD_80721_0001', 'MHR_32_JR0027', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:27:59', '50.187362, 1.628853'),
('Jardins de la Boirie', 17310, 'Nouvelle-Aquitaine', 'Charente-Maritime', '9 Rue Centrale, 17310 Saint-Pierre-d\'Oléron, France', '9 Rue Centrale, 17310 Saint-Pierre-d\'Oléron, France', '9 Rue Centrale', '', 'Saint-Pierre-d\'Oléron', '17385', '17', 75.0, 45.943362000000, -1.2885290000000, '[\"http://www.lesjardinsdelaboirie.com\", \"https://www.facebook.com/Lesjardinsdelaboirie\", \"https://twitter.com/JardinsBoirie\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2006, 'Ce jardin botanique est situé au cœur de la Boirie, vieux village typique de l\'Ile d\'Oléron. Les propriétaires des lieux, véritables passionnés vous feront découvrir leur collection de sauges (plus de 150 espèces), les vivaces et les plantes rares qui participent au charme du lieu. Ce jardin remarquablement entretenu, incite à la flânerie et à la rêverie.', '', 'JARD_17385_0001', 'MHR_75_JR0041', '[]', '[]', '', '2020-09-15 18:19:00', '2022-07-22 10:28:05', '45.943362, -1.288529'),
('Parc de Gerland', 69007, 'Auvergne-Rhône-Alpes', 'Rhône', '69 All. Pierre de Coubertin, 69007 Lyon, France', '69 All. Pierre de Coubertin, 69007 Lyon, France', '69 All. Pierre de Coubertin', '', 'Lyon', '69123', '69', 84.0, 45.724433000000, 4.8269260000000, '[\"http://www.lyon.fr\", \"https://www.facebook.com/pages/Parc-de-Gerland/706460642728064\"]', 'Jardin régulier,Jardin contemporain,Jardin public', 2006, 'Parc paysager contemporain public de 20 hectares, conçu par Michel Corajoud en 2000 à l\'emplacement d\'une ancienne friche industrielle. Prairies, mégaphorbiaie plantée de 300 espèces de végétaux issus de milieu humble, jardins thématiques. Ouvert toute l\'année.', '', 'JARD_69387_0001', 'MHR_84_JR0017', '[]', '[]', '', '2022-03-09 12:54:46', '2022-10-06 18:24:50', '45.724433, 4.826926'),
('Jardin Millésimé du château Haut-Brion', 33850, 'Nouvelle-Aquitaine', 'Gironde', '140 Av. de Cadaujac, 33850 Léognan, France', '140 Av. de Cadaujac, 33850 Léognan, France', '140 Av. de Cadaujac', '', 'Léognan', '33238', '33', 75.0, 44.733303000000, -0.5806770000000, '[\"https://www.larrivethautbrion.fr/jardin-millesime.php\", \"https://twitter.com/chateau_lhb\", \"https://www.instagram.com/chateau_larrivet_haut_brion/\"]', 'Jardin privé', 2020, 'En 2015, Émilie Gervoson initie un projet ambitieux en faisant appel à la scénographe et paysagiste Soline Portmann pour créer un jardin dédié au monde du vin. Le Jardin Millésimé était né. Imaginé dans l\'esprit d\'une parcelle de vigne, les 720 piquets en acacia, peints en rouge et de tailles croissantes, rappellent le vignoble sur 4 000 m2, au cœur du parc arboré du château Larrivet Haut-Brion. Pour composer la palette végétale, Soline Portman est partie d\'une analogie vins / jardin : la mise en scène de la composition végétale et de ses différentes essences rappelle l\'art de l\'assemblage et du travail parcellaire nécessaires à l\'élaboration des grands vins. Les couleurs font référence aux nuances prises par le vin selon les millésimes et leur cycle de vieillissement : du blanc vers le jaune pour le vin blanc et le du rouge foncé vers la rouille pour le vin rouge. Au printemps, la palette dominante est liée aux vins blanc avec des végétaux couleurs anis, vert amande et jaune et des notes aromatiques rappelant les agrumes. L\'été, l\'accent est mis sur les vins rouges, avec des teintes rubis, framboise ; et à l\'automne, saison de maturation du raisin, des dominantes de tabac, de cassis prennent le relais... Le jardin évolue au fur et à mesure et permet de découvrir des textures, des odeurs, de goûter des végétaux rappelant des notes de vin...', '', 'JARD_33238_0001', 'MHR_75_JR0062', '[\"ouvert\"]', '[\"de jour\"]', '', '2022-03-09 12:54:25', '2022-12-20 18:23:02', '44.733303, -0.580677'),
('Jardin de Laroque', 82700, 'Occitanie', 'Tarn-et-Garonne', '303 Fbg Tutet, 82700 Escatalens, France', '303 Fbg Tutet, 82700 Escatalens, France', '303 Fbg Tutet', '', 'Escatalens', '82052', '82', 76.0, 43.986301000000, 1.1847310000000, '[\"http://www.lejardindelaroque.com/\"]', 'Jardin contemporain,Jardin privé', 2020, 'Le jardin de Laroque est un parc créé il y a vingt ans. Il s\'étend sur 2 hectares. A l\'origine, sa vocation était essentiellement nourricière. Il est devenu depuis un jardin ornemental. La présence de nombreuses sources naturelles a permis la création de ruisseaux et bassins, le tout agrémenté de plantes aquatiques. La taille d\'arbres, conifères et arbustes, sous différentes formes (art topiaire) lui confère un caractère particulier. La conception est fortement inspiré du Feng Shui, cet art millénaire d\'origine chinoise qui a pour but d\'harmoniser l\'énergie environnementale d\'un lieu de manière à favoriser la santé, le bien-être et la prospérité de ses visiteurs', '', 'JARD_82052_0001', 'MHR_76_JR0040', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-09 16:36:00', '2022-12-21 11:38:57', '43.986301, 1.184731'),
('Parc du château du Champ de la Pierre', 61320, 'Normandie', 'Orne', '1 Le Château, 61320 Le Champ-de-la-Pierre, France', '1 Le Château, 61320 Le Champ-de-la-Pierre, France', '1 Le Château', '', 'Le Champ-de-la-Pierre', '61085', '61', 28.0, 48.608403000000, -0.2059090000000, '[\"http://www.lechampdelapierre.com\"]', 'Parc paysager,Jardin vivrier,Jardin privé', 2006, 'Les parterres près de la maison sont bordés de tilleuls taillés. Dans le parc se trouvent de beaux hêtres, des pins Weymouth. Deux ports, un labyrinthe, plusieurs fabriques, des allées et des perspectives pleines de charme qui font de ce parc préromantique un lieu de délassement et de rêverie. Des salles vertes offrent de beaux points de vue sur l\'étang. Près de la maison se trouvent l\'ancien potager distribué en quatre carrés comprend une partie légumes et fruits, une partie roseraie et les deux autres parties sont en gazon et en fleurs. Un petit jardin à la française se situe à côté de l\'ancien potager.', '', 'JARD_61085_0001', 'MHR_28_JR0017', '[]', '[]', 'monument historique', '', '2022-07-22 10:28:16', '48.608403, -0.205909'),
('Le Plantier de Costebelle', 83400, 'Provence-Alpes-Côte d\'Azur', 'Var', '7 Av. Edith Wharton, 83400 Hyères, France', '7 Av. Edith Wharton, 83400 Hyères, France', '7 Av. Edith Wharton', '', 'Hyères', '83069', '83', 93.0, 43.120831000000, 6.1224230000000, '[\"https://www.hyeres-tourisme.com/patrimoine-culturel/le-plantier-de-costebelle/\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2009, 'Parc d’acclimatation créé en 1857 par la Baronne de Prailly autour de la maison de l’écrivain P. Bourget. Essences exotiques, arboretum, collection botanique, sculptures et fontaine.', '', 'JARD_83069_0003', 'MHR_93_JR0028', '[]', '[]', 'vpah', '2020-09-15 18:19:00', '2022-07-22 10:28:10', '43.120831, 6.122423'),
('Potager du jardin du château de La Bussière', 45230, 'Centre-Val de Loire', 'Loiret', '30 Rue du Château, 45230 La Bussière, France', '30 Rue du Château, 45230 La Bussière, France', '30 Rue du Château', '', 'La Bussière', '45060', '45', 24.0, 47.747086000000, 2.7494880000000, '[\"http://www.chateau-labussiere.com\", \"https://www.instagram.com/chateaudelabussiere/\"]', 'Jardin régulier,Parc paysager,Jardin vivrier,Jardin privé', 2004, 'Un potager vivrier de traditions à découvrir avec une collection de légumes anciens. \r\n Circuit des cabanes dans le parc pour les enfants (domaine de 60 hectares, potager de 1,5 hectare).', '', 'JARD_45060_0001', 'MHR_24_JR0022', '[]', '[]', 'monument historique', '', '2022-07-22 10:27:50', '47.747086, 2.749488'),
('Parc de la Marseillaise', 68500, 'Grand Est', 'Haut-Rhin', '18 Rte de Soultz, 68500 Guebwiller, France', '18 Rte de Soultz, 68500 Guebwiller, France', '18 Rte de Soultz', '', 'Guebwiller', '68112', '68', 44.0, 47.902944000000, 7.2177150000000, '[\"http://www.ville-guebwiller.fr/\"]', 'Parc paysager,Jardin public', 2006, 'Parc créé entre 1897 et 1899 par l\'architecte-paysagiste parisien Edouard André. Alliant compositions florales et essences exotiques, il est orné d\'un puits Renaissance, d\'une fontaine, d\'un kiosque à musique et d\'un exèdre (copie de celui où s\'asseyait Sarah Bernhardt dans la pièce \"Théodora\" de Victorien Sardou).', '', 'JARD_68112_0001', 'MHR_44_JR0011', '[]', '[]', 'monument historique; vpah', '2020-06-08 09:25:00', '2022-07-22 10:28:48', '47.902944, 7.217715'),
('Jardin Godron', 54000, 'Grand Est', 'Meurthe-et-Moselle', 'CITE JUDICIAIRE, Rue Général Fabvier, 54000 Nancy, France', 'CITE JUDICIAIRE, Rue Général Fabvier, 54000 Nancy, France', 'CITE JUDICIAIRE', '', 'Nancy', '54395', '54', 44.0, 48.678814000000, 6.1717300000000, '[\"http://www.mairie-nancy.fr\"]', 'Jardin de collection,Jardin public', 2011, 'Premier jardin botanique de Nancy, fondé en 1758, il conserve un micocoulier de Provence, un arbre aux quarante écus pleureur, et autre copalme d\'Orient. Il présente également des collections de plantes vivaces et de plantes annuelles utilisées pour le fleurissement communal. Il décline une thématique particulière chaque année avec, en 2014, \"Le latin au jardin\".', '', 'JARD_54395_0002', 'MHR_44_JR0035', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:27:57', '48.678814, 6.17173');
INSERT INTO `liste_des_jardins_remarquables` (`Nom du jardin`, `Code Postal`, `Region`, `Departement`, `Adresse complete`, `Adresse de l’entree du public`, `Numero et libelle de la voie`, `Complement d'adresse`, `Commune`, `Code INSEE`, `Code INSEE Departement`, `Code INSEE Region`, `Latitude`, `Longitude`, `Site Internet et autres liens`, `Types`, `Annee d'obtention`, `Description`, `Auteur / Nom de l'illustre`, `Identifiant DEPS`, `Identifiant origine`, `Accessible au public`, `Conditions d’ouverture`, `Equipement Précision`, `Date de création`, `Date de MAJ`, `coordonnees_geographiques`) VALUES
('Parc Chavat', 33720, 'Nouvelle-Aquitaine', 'Gironde', '26 Rue Pierre Vincent, 33720 Podensac, France', '26 Rue Pierre Vincent, 33720 Podensac, France', '26 Rue Pierre Vincent', '', 'Podensac', '33327', '33', 75.0, 44.657863000000, -0.3624510000000, '[]', 'Jardin régulier,Parc paysager,Jardin de collection,Jardin public', 2011, 'Aujourd’hui public, le parc du château Chavat a été créé en 1918 par un industriel éclairé. Jardin mixte en balcon sur la Garonne habité par une importante statuaire, il présente une grande variété végétale et un parcours d’eau inspiré.', '', 'JARD_33327_0001', 'MHR_75_JR0027', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:04', '44.657863, -0.362451'),
('Jardin d\'Eguilles de Max Sauze', 13510, 'Provence-Alpes-Côte d\'Azur', 'Bouches-du-Rhône', 'Jardin d\'Éguilles, 105 Av. Paul Magallon, 13510 Éguilles, France', 'Jardin d\'Éguilles, 105 Av. Paul Magallon, 13510 Éguilles, France', 'Jardin d\'Éguilles', '', 'Éguilles', '13032', '13', 93.0, 43.571123000000, 5.3529910000000, '[\"http://www.max-sauze.com\"]', 'Jardin contemporain,Jardin privé', 2005, 'Jardin d’artiste au coeur du village mettant en scène de façon poétique une centaine d\'oeuvres de Max Sauze, sculpteur contemporain, dans un monde végétal foisonnant.', '', 'JARD_13032_0001', 'MHR_93_JR0019', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:10', '43.571123, 5.352991'),
('Jardin du manoir d\'Eyrignac', 24590, 'Nouvelle-Aquitaine', 'Dordogne', '545 Eyrignac, 24590 Salignac-Eyvigues, France', '545 Eyrignac, 24590 Salignac-Eyvigues, France', '545 Eyrignac', '', 'Salignac-Eyvigues', '24516', '24', 75.0, 44.939145000000, 1.3153770000000, '[\"http://www.eyrignac.com\", \"https://www.facebook.com/JardinsEyrignac/\", \"https://twitter.com/eyrignac\", \"https://www.instagram.com/eyrignac/\", \"https://www.youtube.com/user/JardinsEyrignac\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2004, 'Ces jardins verts composés de charmes, d’ifs et de buis, ainsi que de cyprès rappelant l’Italie, constituent un exemple de l’art topiaire. Roseraie et jardin potager.', '', 'JARD_24516_0001', 'MHR_75_JR0017', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:17', '44.939145, 1.315377'),
('Parc du château des Milandes', 24250, 'Nouvelle-Aquitaine', 'Dordogne', 'Les Milandes, 24250 Castelnaud-la-Chapelle, France', 'Les Milandes, 24250 Castelnaud-la-Chapelle, France', 'Les Milandes', '', 'Castelnaud-la-Chapelle', '24063', '24', 75.0, 44.826745000000, 1.1178080000000, '[\"https://www.milandes.com\", \"https://www.facebook.com/lechateaudesmilandes/\", \"https://www.instagram.com/chateaudesmilandes/\"]', 'Jardin régulier,Jardin privé', 2018, 'C’est au début du XXe siècle que le jardin actuel fut dessiné : Jules Vacherot, grand architecte paysagiste du début du siècle réalise une prouesse de perspective et fait entrer les Milandes dans le cercle fermé des Jardins Périgourdins inscrits au titre des Monuments Historiques.', '', 'JARD_24086_0001', 'MHR_75_JR0052', '[\"ouvert\"]', '[\"de jour\"]', 'maison des illustres; monument historique', '2018-06-27 17:29:00', '2022-12-20 17:56:18', '44.826745, 1.117808'),
('Jardin de l\'Albarède', 24250, 'Nouvelle-Aquitaine', 'Dordogne', '11 Grand Rue, 24250 Domme, France', '11 Grand Rue, 24250 Domme, France', '11 Grand Rue', '', 'Domme', '24395', '24', 75.0, 44.802244000000, 1.2147030000000, '[\"http://www.jardins-albarede.com\"]', 'Jardin contemporain,Jardin vivrier,Jardin privé', 2006, 'Jardin contemporain cultivé de manière biologique et adapté au site mêlant vieilles pierres, fleurs et senteurs.', '', 'JARD_24395_0001', 'MHR_75_JR0015', '[]', '[]', '', '2020-12-11 13:15:04', '2022-07-22 10:28:17', '44.802244, 1.214703'),
('Jardin de l’habitation Saint-Etienne', 97213, 'Martinique', 'Martinique', 'Habitation Saint-Étienne 97213 Gros-Morne', 'Habitation Saint-Étienne 97213 Gros-Morne', 'Habitation Saint-Étienne', '', 'Gros-Morne', '97212', '972', 2.0, 14.692186000000, -61.0139410000000, '[\"http://pnr-martinique.com/visiter/lhabitation-saint-etienne/\", \"https://www.facebook.com/parcnaturelregionaldelamartinique/\"]', 'Jardin contemporain,Jardin privé', 2015, 'Jardin de cinq hectares organisé autour de plusieurs zones thématiques : la palmeraie, le jardin des balisiers et des plantes à fleurs, la pelouse des arbres anciens et monumentaux, la bambouseraie.', '', 'JARD_97212_0001', 'MHR_02_JR0002', '[]', '[]', '', '2020-12-11 13:14:16', '2022-11-25 12:13:09', '14.692186, -61.013941'),
('Jardin du château de Touffou', 86300, 'Nouvelle-Aquitaine', 'Vienne', '21 Rte de Touffou, 86300 Bonnes, France', '21 Rte de Touffou, 86300 Bonnes, France', '21 Rte de Touffou', '', 'Bonnes', '86031', '86', 75.0, 46.607069000000, 0.5944080000000, '[\"http://www.touffou.com\", \"https://www.facebook.com/ChateauDeTouffou/\", \"https://www.instagram.com/explore/tags/touffou/\"]', 'Jardin régulier,Jardin contemporain,Jardin de collection,Jardin privé', 2004, 'L\'écrin végétal réalisé avec la création de trois jardins différents est en parfaite harmonie avec l\'architecture du château surplombant la Vienne. Le premier se compose de mixed-borders garnis de nombreuses plantes vivaces et d\'une roseraie. Les deux autres ont été créés par le paysagiste Paolo Pejroné. Le jardin de l\'Aumônerie présente onze carrés bordés de buis dont le décor change au fil des ans. En contrebas du château, la terrasse des Tournois accueille le troisième jardin avec ses parterres de buis, plantés de Népeta six Hills Giant.', '', 'JARD_86031_0001', 'MHR_75_JR0005', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:04', '46.607069, 0.594408'),
('Jardin du château Corbelin', 58210, 'Bourgogne-Franche-Comté', 'Nièvre', '271 Corbelin, 58210 La Chapelle-Saint-André, France', '271 Corbelin, 58210 La Chapelle-Saint-André, France', '271 Corbelin', '', 'La Chapelle-Saint-André', '58058', '58', 27.0, 47.380775000000, 3.3313210000000, '[\"http://www.corbelin.com\", \"https://www.facebook.com/Ch%C3%A2teau-de-Corbelin-1439763342940257/\", \"https://www.instagram.com/chateau_de_corbelin/\"]', 'Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2015, 'Le château de Corbelin, château du XVe-XVIe siècle et fini d\'être restauré en 2012 après 15 ans de travaux, est entouré par un jardin autour de l\'eau (étang, rivière, bassin, fontaine, fossé etc.). Le visiteur peut y voir un jardin d\'inspiration italienne (géométrique), un potager décoratif, un verger entouré d\'eau.', '', 'JARD_58058_0001', 'MHR_27_JR0004', '[]', '[]', '', '', '2022-10-07 18:59:21', '47.380775, 3.331321'),
('Roseraie du Val-de-Marne', 94240, 'Île-de-France', 'Val-de-Marne', 'Rue Watel 94240 L\'Haÿ-les-Roses', 'Rue Watel 94240 L\'Haÿ-les-Roses', 'Rue Watel', '', 'L\'Haÿ-les-Roses', '94038', '94', 11.0, 48.776998000000, 2.3341270000000, '[\"http://www.roseraieduvaldemarne.fr\"]', 'Jardin régulier,Jardin de collection,Jardin public', 2011, 'Œuvre de Jules Gravereaux, la Roseraie fut dessinée en 1899 par Edouard André. Il s’agit de la première roseraie occidentale. Véritable conservatoire vivant de roses anciennes, la roseraie actuelle présente une chronologie de collections exceptionnelles.', '', 'JARD_94038_0001', 'MHR_11_JR0024', '[]', '[]', 'monument historique', '', '2022-11-28 15:57:55', '48.776998, 2.334127'),
('Jardin du pin', 49123, 'Pays de la Loire', 'Maine-et-Loire', '1310 Le Haut Pin, 49123 Champtocé-sur-Loire, France', '1310 Le Haut Pin, 49123 Champtocé-sur-Loire, France', '1310 Le Haut Pin', '', 'Champtocé-sur-Loire', '49068', '49', 52.0, 47.439940000000, -0.8529100000000, '[\"http://www.jardinsduchateaudupin.com/\"]', 'Jardin régulier,Parc paysager,Jardin vivrier,Jardin privé', 2006, 'Forte géométrie et influences anglaises ont présidé à la conception de ces jardins en 1921. Près du château et de l\'orangerie, les terrasses d\'ardoises, bassins et ifs monumentaux s\'insèrent dans un parc paysager aux essences rares. L\'ancien potager accueille une importante collection de rosiers. Prix anglais ETBS de l\'art topiaire international en 2014.', '', 'JARD_49068_0001', 'MHR_52_JR0004', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:49', '47.43994, -0.85291'),
('Serre de la Madone', 6500, 'Provence-Alpes-Côte d\'Azur', 'Alpes-Maritimes', '169 Cor André Tardieu, 06500 Menton, France', '169 Cor André Tardieu, 06500 Menton, France', '169 Cor André Tardieu', '', 'Menton', '6083', '6', 93.0, 43.796582000000, 7.4866560000000, '[\"http://www.serredelamadone.com\"]', 'Jardin de collection,Jardin public', 2005, 'Jardin créé entre 1924 et 1939, d’une surface de 8 hectares dont 4 sont ouverts à la visite. C’est au cœur de la vallée de Gorbio que Lawrence Johnston, créateur de Hidcote Manor en Angleterre, a aménagé son \"Paradis Terrestre\" : plantes rares rapportées du monde entier et mises en valeur entre bassins, fontaines, statues et escaliers à volutes…', '', 'JARD_06083_0003', 'MHR_93_JR0010', '[]', '[]', 'monument historique; vpah', '2020-06-08 09:24:00', '2022-07-22 10:28:46', '43.796582, 7.486656'),
('Jardin de Baudouvin', 83160, 'Provence-Alpes-Côte d\'Azur', 'Var', '116 Rue des Jardins, 83160 La Valette-du-Var, France', '116 Rue des Jardins, 83160 La Valette-du-Var, France', '116 Rue des Jardins', '', 'La Valette-du-Var', '83144', '83', 93.0, 43.140010000000, 5.9858450000000, '[\"https://www.lavalette83.fr/ma-ville/patrimoine-naturel/baudouvin/\", \"https://www.instagram.com/jardindebaudouvin/\"]', 'Jardin régulier,Jardin vivrier,Jardin public', 2009, 'Jardins de 3 hectares créé au XIXe siècle autour d\'une Bastide Provençale du XVIIIe siècle', '', 'JARD_83144_0002', 'MHR_93_JR0032', '[]', '[]', '', '2022-03-09 12:54:56', '2022-07-22 10:28:11', '43.14001, 5.985845'),
('Jardin et parc du château de Compiègne', 60200, 'Hauts-de-France', 'Oise', '2 Rue du Dahomey, 60200 Compiègne, France', '2 Rue du Dahomey, 60200 Compiègne, France', '2 Rue du Dahomey', '', 'Compiègne', '60159', '60', 32.0, 49.418052000000, 2.8293690000000, '[\"http://www.musee-chateau-compiegne.fr\"]', 'Jardin régulier,Parc paysager,Jardin public', 2004, 'Le parc du château de Compiègne offre une composition harmonieuse et originale dans un riche environnement patrimonial. Berceau de verdure, offrant une riche floraison printanière, ainsi que des végétaux remarquables (un hêtre pourpre planté sous Napoléon III), le parc du château de Compiègne est un site riche et incontournable pour les passionnés d’horticulture.', '', 'JARD_60159_0001', 'MHR_32_JR0015', '[]', '[]', 'monument historique; musee de france', '2020-06-08 09:23:00', '2022-07-22 10:27:58', '49.418052, 2.829369'),
('Jardin Georges Delaselle', 29253, 'Bretagne', 'Finistère', '100 Penn Baz, 29253 Île-de-Batz, France', '100 Penn Baz, 29253 Île-de-Batz, France', '100 Penn Baz', '', 'Île-de-Batz', '29082', '29', 53.0, 48.741996000000, -3.9944610000000, '[\"http://jardin-georgesdelaselle.com/\", \"https://www.facebook.com/JardinGeorgesDelaselle\", \"https://www.instagram.com/jardin.delaselle/\"]', 'Jardin de collection,Jardin privé', 2005, 'Jardin tropical créé à la fin du 19e siècle par Georges Delaselle dans un site où fut exhumée une nécropole de l’Age du Bronze. Restauré et agrandi dans les années 1990, ce jardin dont l’organisation spatiale et la composition végétale, d’une grande richesse botanique, associe notamment palmeraie, cacteraie, pelouse de cordylines et plantes des terres australes, compose un ensemble harmonieux qui privilégie les ambiances exotiques dans la fidélité à l’esprit romantique des origines (2 ha).', '', 'JARD_29082_0001', 'MHR_53_JR0009', '[]', '[]', '', '2020-12-11 13:16:09', '2022-10-07 23:01:41', '48.741996, -3.994461'),
('Jardin de l\'écomusée des monts du Forez', 42550, 'Auvergne-Rhône-Alpes', 'Loire', '8 Pl. de la Vialle, 42550 Usson-en-Forez, France', '8 Pl. de la Vialle, 42550 Usson-en-Forez, France', '8 Pl. de la Vialle', '', 'Usson-en-Forez', '42318', '42', 84.0, 45.391095000000, 3.9406680000000, '[\"http://www.ecomusee-usson-en-forez.fr\", \"https://www.facebook.com/ecomuseedesmontsduforez/\"]', 'Jardin contemporain,Jardin de collection,Jardin vivrier', 2006, 'Jardin de 240 m² recréé en 2001 dans l\'esprit des jardins de curé à partir de témoignages et de photographies anciennes. 8 espaces délimités par une rangée de petits buis présentent 100 variétés de plantes potagères, médicinales, ornementales et aromatiques.', '', 'JARD_42318_0001', 'MHR_84_JR0030', '[]', '[]', 'vpah', '2020-06-08 09:24:00', '2022-07-22 10:27:56', '45.391095, 3.940668'),
('Bambouseraie de Prafrance', 30140, 'Occitanie', 'Gard', '66 Rue de Perache, 30140 Générargues, France', '66 Rue de Perache, 30140 Générargues, France', '66 Rue de Perache', '', 'Générargues', '30129', '30', 76.0, 44.074423000000, 3.9796300000000, '[\"http://www.bambouseraie.fr\", \"https://www.facebook.com/bambouseraie.en.cevennes\", \"https://www.instagram.com/bambouseraie.en.cevennes/\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2006, 'Aujourd\'hui jardin exotique unique en Europe, la Bambouseraie a été créée en 1856 par un amateur passionné du monde végétal Eugène Mazel. Associés à une riche collection de plantes exotiques et d\'arbres remarquables, les bambous constituent l\'originalité botanique de la Bambouseraie. Forêt de bambous géants unique en Europe, aménagements paysagers exceptionnels tels le Bambusarium, le labyrinthe végétal, le jardin des bassins d\'Eugène, le village laotien transportent le visiteur dans les pays lointains. Erik Borja, artiste paysagiste, a créé le Vallon du Dragon qui s\'insère non seulement dans la Bambouseraie mais aussi dans le paysage cévenol et surprend plus d\'un visiteur. Ce jardin de promenade à la japonaise joue sur la complémentarité du végétal et du minéral dans lequel les floraisons printanières et les couleurs d\'automne ont un rôle majeur. La Bambouseraie de Prafrance oeuvre pour le développement des collections qui permettent la conservation du patrimoine génétique de la planète, essentielle au maintien de la biodiversité. Ouverte à la recherche, à la culture, à l\'art, elle accueille chaque année des artistes dont les installations in situ sont souvent inspirées par le végétal.', '', 'JARD_30129_0001', 'MHR_76_JR0003', '[]', '[]', 'monument historique', '', '2022-07-22 10:28:06', '44.074423, 3.97963'),
('Jardin du prieuré de Locmaria', 29000, 'Bretagne', 'Finistère', '2 Pl. Berardier, 29000 Quimper, France', '2 Pl. Berardier, 29000 Quimper, France', '2 Pl. Berardier', '', 'Quimper', '29232', '29', 53.0, 47.988549000000, -4.1121870000000, '[\"http://www.quimper.bzh/383-jardins-remarquables.htm#par4048\"]', 'Jardin contemporain,Jardin public', 2008, 'Jardin municipal d\'inspiration médiévale, aménagé à partir de 1997 sur une rive de l\'Odet dans l\'esprit des jardins de monastères de l\'époque d\'Anne de Bretagne. Plusieurs massifs sont consacrés aux plantes culinaires, médicinales ou ramenées de croisades, et à des arbres fruitiers. Au centre, un kiosque abrite une fontaine, symbole de la source de vie irriguant le paradis.', '', 'JARD_29232_0001', 'MHR_53_JR0013', '[]', '[]', '', '2020-09-15 18:16:00', '2022-10-11 22:02:13', '47.988549, -4.112187'),
('Jardin des fontaines pétrifiantes', 38840, 'Auvergne-Rhône-Alpes', 'Isère', '184 Imp. des Tufières, 38840 La Sône, France', '184 Imp. des Tufières, 38840 La Sône, France', '184 Imp. des Tufières', '', 'La Sône', '38495', '38', 84.0, 45.112710000000, 5.2807090000000, '[\"http://www.visites-nature-vercors.com/fr/jardin/decouvrez-notre-jardin/\", \"https://www.facebook.com/jardin.fontaines\"]', 'Jardin privé', 2019, 'Le Jardin des Fontaines Pétrifiantes est un lieu de découverte et de détente. L\'eau accompagne le visiteur dans ce site féerique où le travail des jardiniers met en valeur de nombreuses espèces végétales avec humour et poésie. Les sources du jardin, exceptionnellement calcaires, donnent naissance aux fontaines pétrifiantes, les tufières. Ces structures naturelles de plusieurs mètres sont le résultat de la transformation des végétaux en roche. Elles forment un écrin pour un jardin luxuriant où petits et grands s\'émerveillent.', '', 'JARD_38495_0001', 'MHR_84_JR0031', '[\"ouvert\"]', '[\"saisonnière\"]', '', '2020-06-09 16:36:00', '2022-12-15 17:03:40', '45.11271, 5.280709'),
('Jardin du château royal d’Amboise', 37400, 'Centre-Val de Loire', 'Indre-et-Loire', '5 Mnt de l\'Emir Abd el Kader, 37400 Amboise, France', '5 Mnt de l\'Emir Abd el Kader, 37400 Amboise, France', '5 Mnt de l\'Emir Abd el Kader', '', 'Amboise', '37003', '37', 24.0, 47.412988000000, 0.9847220000000, '[\"http://www.chateau-amboise.com/n/fr/\", \"https://www.facebook.com/chateauroyaldamboise/\", \"https://twitter.com/ChateauAmboise\", \"https://www.instagram.com/chateau_amboise/\"]', 'Jardin régulier,Jardin contemporain,Jardin public', 2017, 'Surplombant la ville d\'Amboise et La Loire, eau élément remarquable, les jardins du Château offrent l\'un des plus beaux panoramas du Val de Loire. Plusieurs ensembles les composent : - l\'esplanade d\'Honneur et ses allées Renaissance - la terrasse Nord, - la partie boisée, sur toute la partie Est, avec cyprès et buis taillés - le fossé et le bastion extérieur. Création du Jardin de Midi : vous accèderez à une terrasse jusqu\'à présent inaccessible qui offre un panorama sur la ville d\'Amboise et le Clos Lucé tout proche. Ce jardin contemporain orienté au midi est planté d\'essences méditerranéennes. -Création du Jardin d\'Orient : espace de souvenir en hommage à la présence de l\'Emir Abd El Kader et de sa suite autour de 25 pierres d\'Alep gravées d\'hymnes à la paix des extraits du Coran qui invitent à la médidation et au recueillement.', '', 'JARD_37003_0001', 'MHR_24_JR0030', '[\"ouvert\"]', '[\"à l’année\", \"de jour\"]', '', '2020-06-08 09:25:00', '2022-12-16 16:57:33', '47.412988, 0.984722'),
('Jardins du donjon de Ballon', 72290, 'Pays de la Loire', 'Sarthe', '2 Rue du Château, 72290 Ballon-Saint-Mars, France', '2 Rue du Château, 72290 Ballon-Saint-Mars, France', '2 Rue du Château', '', 'Ballon-Saint-Mars', '72023', '72', 52.0, 48.177109000000, 0.2332590000000, '[\"http://www.donjondeballon.fr\", \"https://www.facebook.com/chateaudeballon\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2007, 'Au pied d\'un donjon-forteresse du XIe siècle, les jardins de Ballon sont labellisés \"Jardin Remarquable\". Un premier jardin, clos, est constitué de buis et de plantes aromatiques. Le second comprend une collection d’arbres fruitiers botaniques poiriers, pommiers, pruniers, cerisiers entre lesquels se déploient des roses anciennes, clématites et pivoines arbustives. Du sommet de la motte féodale construite sur un éperon rocheux, on découvre un point de vue panoramique exceptionnel à plus de 40 km sur le Parc Maine-Normandie et le pays saôsnois.', '', 'JARD_72023_0001', 'MHR_52_JR0009', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:11', '48.177109, 0.233259'),
('Jardin animalier de l\'Anse Latouche', 97221, 'Martinique', 'Martinique', 'Anse Latouche, Le Carbet 97221, Martinique', 'Anse Latouche, 97221 Le Carbet, France', 'Anse Latouche', '', 'Le Carbet', '97204', '972', 2.0, 14.704936000000, -61.1703130000000, '[\"https://www.zoodemartinique.com\"]', 'Jardin contemporain', 2022, 'C’est au sein de cette ancienne habitation martiniquaise, détruite en 1902 par l’éruption de la montagne Pelée que la flore du monde entier rassemblée avec passion par Monsieur Thoze se développe entre les enclos paysagers et la faune sauvage. \r\nAvec de nombreux panneaux explicatifs, le visiteur apprend à connaitre les spécificités des espèces présentes et l’histoire du site dont les vestiges sont bien souvent valorisés comme enclos. \r\nÉléments remarquables : les vestiges de l’ancien moulin (roue à aube), de la maison de maitre et de la poterie. \r\nL’imposant barrage en pierre sur la rivière Latouche et les ponts suspendus en bois qui raviront les amoureux des sensations fortes…', '', '', '', '[\"ouvert\"]', '[]', '', '2022-12-14 17:06:45', '2023-01-11 11:43:03', '14.704936, -61.170313'),
('Parc du château de Courances', 91490, 'Île-de-France', 'Essonne', '10 Rue Saint-Charles, 91490 Courances, France', '10 Rue Saint-Charles, 91490 Courances, France', '10 Rue Saint-Charles', '', 'Courances', '91180', '91', 11.0, 48.441482000000, 2.4756800000000, '[\"http://www.courances.net\", \"https://www.instagram.com/chateaudecourances/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Courances : le parc dont Le Nôtre s\'est inspiré, considéré comme l’un des 10 plus beaux parcs de France ; les Jardins d\'eau datent de la Renaissance et recèlent 14 sources et 17 pièces d\'eau. Les arbres ne sont pas taillés en rideau, ils créent des voûtes au-dessus de l\'eau et l\'on marche presque partout sur l\'herbe. Cinq siècles d\'histoire des jardins qui s\'illustrent aussi avec le célèbre Jardin japonais aménagé par Berthe de Ganay au début du XXe siècle. A Courances, on ressent plus fortement la présence de la nature que dans d\'autres parcs et la liberté de ceux qui n\'ont cessé de réinventer ces lieux.\r\n -Défilé de voitures anciennes le dimanche 1er juin à partir de 12h00; les visiteurs peuvent apporter leur picnic dans le parc.\r\n - Food design : vente de brunch et ateliers pour enfants\r\n - Visites guidées du parc', '', 'JARD_91180_0001', 'MHR_11_JR0002', '[]', '[]', 'monument historique', '2020-09-15 18:19:00', '2022-07-22 10:27:59', '48.441482, 2.47568'),
('Jardins du château de Viven', 64450, 'Nouvelle-Aquitaine', 'Pyrénées-Atlantiques', '930 Chem. du Château, 64450 Viven, France', '930 Chem. du Château, 64450 Viven, France', '930 Chem. du Château', '', 'Viven', '64560', '64', 75.0, 43.458613000000, -0.3794860000000, '[\"http://www.chateau-de-viven.com\"]', 'Jardin régulier,Parc paysager,Jardin contemporain,Jardin vivrier,Jardin privé', 2007, 'Autour de la demeure du XVIIIe siècle, jardin régulier en terrasse, topiaires et labyrinthe de buis, roseraie et jardins à thèmes.', '', 'JARD_64560_0001', 'MHR_75_JR0034', '[]', '[]', 'monument historique', '2020-09-15 18:15:00', '2022-07-22 10:28:05', '43.458613, -0.379486'),
('Parc floral de Paris', 75012, 'Île-de-France', 'Paris', 'route de la Pyramide, 75012 Paris, France', 'Route de la Pyramide, 75012 Paris, France', 'Route de la Pyramide', '', 'Paris', '75056', '75', 11.0, 48.840436859477, 2.4363638331906, '[\"https://www.parcfloraldeparis.com/fr\"]', 'Parc paysager,Jardin de collection,Jardin public', 2018, 'Le Parc Floral met en scène la flore régionale dans des paysages typiques et représentatifs d’écosystèmes menacés. Son Chemin de l’Évolution invite à la découverte de la longue histoire des végétaux. Créé en 1969, ce site de trente hectares présente aussi d’importantes collections botaniques et horticoles, en extérieur et dans les pavillons : plantes régionales, plantes du Jurassique, plantes médicinales, plantes accrobranchées, bonsaïs, fougères, pivoines, pélargoniums, géraniums, astilbes, iris, dahlias… Le concours international du dahlia se déroule chaque année fin septembre.', '', 'JARD_75112_0001', 'MHR_11_JR0032', '[\"ouvert\"]', '[\"de jour\"]', '', '2022-03-09 12:54:49', '2022-12-20 09:31:54', '48.840436859477, 2.4363638331906'),
('Jardins de Cistus', 79150, 'Nouvelle-Aquitaine', 'Deux-Sèvres', '2 Imp. des Garages, 79150 Argentonnay, France', '2 Imp. des Garages, 79150 Argentonnay, France', '2 Imp. des Garages', '', 'Argentonnay', '79013', '79', 75.0, 46.954270000000, -0.3897440000000, '[]', 'Jardin contemporain,Jardin privé', 2015, 'Créé à partir de 1996 à l\'emplacement d\'une prairie, ce magnifique jardin proche de la rivière Argenton présente de nombreux conifères, chênes verts, magnolias et essences caduques. Dans une succession d\'ambiances différentes, le visiteur découvrira également des arbustes à fleurs (malus, prunus, cornus, halesia, clérodendrons), plusieurs cistes ainsi que des plantes de terre de bruyère. Plusieurs massifs plantés de vivaces aux couleurs harmonieuses agrémentent ce petit coin de paradis.', '', 'JARD_79013_0001', 'MHR_75_JR0044', '[]', '[]', '', '', '2022-10-07 22:54:55', '46.95427, -0.389744'),
('Jardin des Cinq sens', 74140, 'Auvergne-Rhône-Alpes', 'Haute-Savoie', '11 Rue du Lac, 74140 Yvoire, France', '11 Rue du Lac, 74140 Yvoire, France', '11 Rue du Lac', '', 'Yvoire', '74315', '74', 84.0, 46.370657000000, 6.3259190000000, '[\"http://www.jardin5sens.net\", \"https://www.facebook.com/jardin5sens/\", \"https://www.instagram.com/jardin5sens/\"]', 'Jardin d\'inspiration médiévale,Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2004, 'Situé sur les rives du lac Léman, ce Jardin privé de 2500 m2 est un écrin végétal inspiré des labyrinthes du Moyen-Age. Plusieurs jardins intimistes invitent à l’éveil des sens et à la découverte d’une grande diversité de plantes. Cette œuvre vivante a été créée par Yves et Anne-Monique d’Yvoire avec le concours d’Alain Richert et d’André Gayraud.', '', 'JARD_74315_0001', 'MHR_84_JR0023', '[]', '[]', '', '', '2022-10-06 18:30:36', '46.370657, 6.325919'),
('Jardin botanique de l\'université Louis Pasteur', 67000, 'Grand Est', 'Bas-Rhin', '28 Rue Goethe, 67000 Strasbourg, France', '28 Rue Goethe, 67000 Strasbourg, France', '28 Rue Goethe', '', 'Strasbourg', '67482', '67', 44.0, 48.584201000000, 7.7666130000000, '[\"http://www.jardin-botanique.unistra.fr\"]', 'Jardin de collection,Jardin public', 2006, 'Le jardin botanique de l\'Université de Strasbourg a été créé en 1619. Son emplacement actuel date de 1884. Il est riche de plus de 6000 espèces. Les collections sont réparties sur 3,5 hectares de jardin. Ensemble de serres, dont une est classée aux Monuments historiques. Autant de centres d\'intérêt qui révèlent au visiteur l\'infinie richesse du monde végétal.', '', 'JARD_67482_0001', 'MHR_44_JR0008', '[]', '[]', 'monument historique', '', '2022-07-22 10:28:18', '48.584201, 7.766613'),
('Jardin des Barthes', 40230, 'Nouvelle-Aquitaine', 'Landes', '480 chemin Lasseougue, 40230 Saubrigues, France', '480 chemin Lasseougue, 40230 Saubrigues, France', '480 chemin Lasseougue', '', 'Saubrigues', '40036', '40', 75.0, 43.587548000000, -1.3344680000000, '[\"https://www.jardindesbarthes.com\", \"https://www.instagram.com/jardin_des_barthes\"]', 'Parc paysager,Jardin contemporain,Jardin de collection,Jardin privé', 2021, 'La propriétaire, paysagiste aguerrie, a installé, sur la pente douce d’une colline, face à la chaîne des Pyrénées, son jardin de cinq hectares, créé de toute pièce sur une ancienne terre agricole. Alternant espaces ouverts au sommet et espaces fermés en sous-bois, elle a profité des atouts bioclimatiques de la région et du terrain pour créer une canopée humide foisonnante sous un bois de chênes et de châtaigniers parsemé de quelques pins.', '', '', '', '[]', '[]', '', '2022-09-08 17:03:17', '2022-09-08 17:08:41', '43.587548, -1.334468'),
('Jardin du Tomple', 30450, 'Occitanie', 'Gard', '184 La Bise Basse, 30450 Concoules, France', '184 La Bise Basse, 30450 Concoules, France', '184 La Bise Basse', '', 'Concoules', '30090', '30', 76.0, 44.377411000000, 3.9477280000000, '[\"http://jardindutomple.canalblog.com\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2004, 'Au pied du Mont Lozère, près d’un grand mas cévenol, un jardin secret révèle dans un désordre botanique et un esprit \"jardin anglais\", une riche collection de rosiers, d\'hydrangeas, de pivoines et de plantes vivaces. L’eau est omniprésente et rythme le parcours de ce jardin passion, toujours en mouvement, qui révèle des surprises à chaque détour.', '', 'JARD_30090_0001', 'MHR_76_JR0006', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:18', '44.377411, 3.947728'),
('Les jardins de Sothys', 19220, 'Nouvelle-Aquitaine', 'Corrèze', '10 Rue Bernard Mas, 19220 Auriac, France', '10 Rue Bernard Mas, 19220 Auriac, France', '10 Rue Bernard Mas', '', 'Auriac', '19014', '19', 75.0, 45.201392000000, 2.1420410000000, '[\"https://www.lesjardinssothys.fr/\", \"https://www.facebook.com/LesJardinsSothys/\", \"https://www.instagram.com/lesjardinssothys/\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2017, 'Créés en 2007 sur 4 hectares, au cœur d’un écrin végétal préservé et riche de sa diversité, terre d’origine de la famille Mas, Les Jardins Sothys valorisent le monde végétal ; ils sont la source d’inspiration et de création des produits cosmétiques Sothys. La philosophie Sothys est vouée à la beauté, à la cosmétique et au bien-être. Tout à la fois jardins d’ambiances, ensemble de petits clos intimistes aux atmosphères variées, ils vous invitent à une évasion sensorielle, une expérience unique qui allie nature, beauté et culture. En vous y perdant vous ressentirez harmonie, sérénité et calme. Les créateurs des jardins Sothys ne cessent chaque année de faire appel à leur imagination et à celle de leurs équipes.', '', 'JARD_19014_0001', 'MHR_75_JR0048', '[]', '[]', '', '2020-12-11 13:14:42', '2022-12-07 22:08:49', '45.201392, 2.142041'),
('Jardin de la Mothe', 12260, 'Occitanie', 'Aveyron', 'Le Bourg, 12260 Salles-Courbatiès, France', 'Le Bourg, 12260 Salles-Courbatiès, France', 'Le Bourg', '', 'Salles-Courbatiès', '12252', '12', 76.0, 44.471560000000, 2.0779510000000, '[\"http://www.jardindelamothe.com\", \"https://www.instagram.com/jardin.delamothe/\"]', 'Jardin contemporain,Jardin vivrier,Jardin privé', 2013, 'Créés en 1997 autour d’une ancienne ferme aveyronnaise, jardin privé d\'artiste de 3 500 m2 composé d’espaces intimes, mettant en scène des tableaux sur le paysage. Les espèces végétales choisies sont particulièrement adaptées au sol et au climat rude de cette partie du département et dialoguent avec le minéral. Potager, pergola, allée de tilleuls, rosiers, vue panoramique.', '', 'JARD_12252_0001', 'MHR_76_JR0018', '[]', '[]', '', '', '2022-07-22 10:28:08', '44.47156, 2.077951'),
('Jardins du château de Gastines', 49150, 'Pays de la Loire', 'Maine-et-Loire', '14 Rue de Gastine, 49150 Baugé en Anjou, France', '14 Rue de Gastine, 49150 Baugé en Anjou, France', '14 Rue de Gastine', '', 'Baugé en Anjou', '49018', '49', 52.0, 47.625445000000, -0.1467400000000, '[\"https://www.jardinspaysdelaloire.fr/chateau-et-parc-de-gastines.html\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2011, 'En 1990, la création d\'un jardin régulier constitué de plusieurs entités closes de charmilles savamment taillées est confiée en partie, au paysagiste Louis Benech qui soigne particulièrement la transition de ce jardin \"formel\" avec le paysage et le château médiéval.', '', 'JARD_49018_0001', 'MHR_52_JR0005', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:49', '47.625445, -0.14674'),
('Domaine national du château de Pau', 64000, 'Nouvelle-Aquitaine', 'Pyrénées-Atlantiques', 'Rue du Château, 64000 Pau, France', 'Rue du Château, 64000 Pau, France', 'Rue du Château', '', 'Pau', '64445', '64', 75.0, 43.295114100000, -0.3741933000000, '[\"https://chateau-pau.fr\"]', 'Jardin régulier,Parc paysager,Jardin public', 2021, 'Véritable poumon vert de la ville, le parc historique occupe 23 hectares le long du Gave, refuge pour les habitants et la biodiversité. Classé au titre des monuments historiques depuis 2004, il est constitué de trois entités : jardin de carrés de simples sur les terrasses du château, jardin de la basse-plante, et parc en partie forestier sur l’éperon rocheux et paysager dans le vallon. Le parc est doté d’un plan de gestion depuis 2020.', '', '', '', '[]', '[]', '', '2022-09-08 17:14:15', '2022-09-08 17:19:44', '43.2951141, -0.3741933'),
('Verger de Déduit', 15380, 'Auvergne-Rhône-Alpes', 'Cantal', '2 Chapsières, 15380 Anglards-de-Salers, France', '2 Chapsières, 15380 Anglards-de-Salers, France', '2 Chapsières', '', 'Anglards-de-Salers', '15006', '15', 84.0, 45.184084000000, 2.4827990000000, '[\"https://www.facebook.com/chateauTremoliere\"]', 'Jardin contemporain,Jardin privé', 2006, 'Jardin contemporain d’inspiration médiévale. Jardin clos de murs en pierre sèche né du mariage entre l’imaginaire pictural de la collection de tapisseries \"le Bestiaire Fantastique\" et l’imaginaire littéraire \"le roman de la rose\". Le visiteur viendra à la rencontre du propriétaire Déduit et poursuivra son chemin en traversant des enclos successifs qui le conduiront à une fontaine où il apercevra le reflet de la rose.', '', 'JARD_15006_0001', 'MHR_84_JR0002', '[]', '[]', '', '2020-06-08 09:23:00', '2022-10-06 18:42:52', '45.184084, 2.482799'),
('Parc du moulin à tan et serres de collections tropicales', 89100, 'Bourgogne-Franche-Comté', 'Yonne', '28 Chem. de Babie, 89100 Sens, France', '28 Chem. de Babie, 89100 Sens, France', '28 Chem. de Babie', '', 'Sens', '89387', '89', 27.0, 48.184470000000, 3.2783350000000, '[\"https://www.tourisme-sens.com/visite-musee/parc-du-moulin-a-tan-et-serres-de-collections-tropicales/\"]', 'Parc paysager,Jardin contemporain,Jardin de collection,Jardin public', 2011, 'Ce parc magnifique, avec son moulin, comporte une succession de scènes paysagères à vocations différentes. Vous y découvrirez l\'Arboretum, l\'enclos animalier, une roseraie \"sauvage\" riche en rosiers botaniques, des aires de jeux d\'enfants ainsi qu\'une collection d\'oiseaux aquatiques.\r\n Au cours de cette promenade ombragée entre les cours d\'eau de la Vanne et de la Lingue, s\'illustrera l\'univers des plantes de sous-bois, au travers de collections végétales thématiques (couvre-sols, fougères, arbustes, allée de senteurs). De nouvelles collections végétales (hêtre, bouleau) viennent enrichir ce joyau du patrimoine sénonais.\r\n Un site d\'observation présente toute la faune locale, un rucher.\r\n Des serres de collection tropicales présentent sur 600 m² un parcours dépaysant au cours duquel vous croiserez la célèbre Victoria cruziana, des orchidées dans un jardin d\'Hiver, des cactées et autres plantes épiphytes.', '', 'JARD_89387_0001', 'MHR_27_JR0015', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:27:53', '48.18447, 3.278335'),
('Jardins du musée international de la parfumerie', 6370, 'Provence-Alpes-Côte d\'Azur', 'Alpes-Maritimes', '979 Chemin des Gourettes, 06370 Mouans-Sartoux, France', '979 Chemin des Gourettes, 06370 Mouans-Sartoux, France', '979 Chemin des Gourettes', '', 'Mouans-Sartoux', '6084', '6', 93.0, 43.614830000000, 6.9790650000000, '[\"http://www.museesdegrasse.com\", \"https://www.facebook.com/amisduJMIP\"]', 'Jardin contemporain,Jardin de collection,Jardin public', 2022, '\"C’est à une véritable immersion dans un univers olfactif que nous invitent les jardins du Musée International de la Parfumerie de Grasse. Ce conservatoire des plantes à parfum a été créé sur les terres d’une ancienne bastide de Mouans-Sartoux où, dans les années 50, le jasmin et la rose étaient encore cultivés. Articulé de part et d’autre d’un ancien canal en pierre et son bassin, il présente côté sud-est de petits jardins réunissant des végétaux classés, comme le font les parfumeurs, selon des notes épicées, florales, fruitées, aromatiques ou hespéridées se succèdent en paliers.\r\nCôté nord-ouest, de larges restanques sont dévolues aux cultures de plein champ des fleurs les plus emblématiques de la parfumerie grassoise, au fil des saisons : tubéreuse, iris, jasmin, géranium rosat, rose centifolia ou rose de mai… \r\nLes jardins du MIP participent à la conservation et à la mise en valeur des savoir-faire liés au Parfum, inscrits au patrimoine culturel immatériel de l’Humanité par l’Unesco en 2018.', '', '', '', '[\"ouvert\"]', '[]', '', '2022-09-08 15:17:42', '2022-09-08 15:23:30', '43.61483, 6.979065'),
('Les Prés Fichaux', 18000, 'Centre-Val de Loire', 'Cher', '11 Av. de la Libération, 18000 Bourges, France', '11 Av. de la Libération, 18000 Bourges, France', '11 Av. de la Libération', '', 'Bourges', '18033', '18', 24.0, 47.102180000000, 2.4046810000000, '[\"http://www.ville-bourges.fr\"]', 'Jardin régulier,Jardin contemporain,Jardin public', 2004, 'Jardin de style Art décoratif avec arcades d\'ifs taillés, théâtre de verdure et roseraie (4,5 hectares).', '', 'JARD_18033_0001', 'MHR_24_JR0004', '[]', '[]', 'monument historique', '2021-05-19 18:40:18', '2022-07-22 10:27:50', '47.10218, 2.404681'),
('Jardin exotique et botanique', 29680, 'Bretagne', 'Finistère', '152 Rue de Ruveic, 29680 Roscoff, France', '152 Rue de Ruveic, 29680 Roscoff, France', '152 Rue de Ruveic', '', 'Roscoff', '29239', '29', 53.0, 48.714275000000, -3.9764150000000, '[\"http://www.jardinexotiqueroscoff.com\", \"https://www.facebook.com/JardinExotiqueDeRoscoff/\", \"https://www.instagram.com/jardin_exotique_de_roscoff/\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2005, 'Jardin botanique créé à la fin de années 1980 en bordure du littoral. Animé par un groupement associatif, il présente une collection de quelque 3000 plantes subtropicales ou exotiques, provenant en majorité des régions tempérées de l\'hémisphère sud (Afrique du Sud, Amérique du Sud, Australie, Nouvelle-Zélande) mais aussi de zones semi-arides (Asie, Afrique, Amérique du Nord) ou encore d’îles de l\'Atlantique comme les Canaries ou Madère. Jardin conservatoire d’espèces en voie de disparition (1,7 ha).', '', 'JARD_29239_0001', 'MHR_53_JR0014', '[]', '[]', '', '', '2022-07-22 10:27:59', '48.714275, -3.976415'),
('Jardin des Martels', 81500, 'Occitanie', 'Tarn', '1709 Route de Rieu Vergnet 81500 Giroussens', '1709 Route de Rieu Vergnet 81500 Giroussens', '1709 Route de Rieu Vergnet', '', 'Giroussens', '81011', '81', 76.0, 43.777751000000, 1.7962560000000, '[\"http://www.jardinsdesmartels.com\", \"https://www.facebook.com/JardinsDesMartels\"]', 'Parc paysager,Jardin privé', 2006, 'Jardin privé de 3,5 hectares à l\'anglaise. Plus de 2 600 variétés. Serre exotique aquatique. Labyrinthe de bambous. Pagode artisanale balinaise. Collection de nymphéas et de lotus. Temple du lotus. Mini-ferme. Belvédère sur jardins en terrasse. Jardinerie.', '', 'JARD_81104_0001', 'MHR_76_JR0031', '[]', '[]', '', '2020-06-08 09:24:00', '2022-11-25 14:16:26', '43.777751, 1.796256'),
('Un jardin philosophe', 67530, 'Grand Est', 'Bas-Rhin', 'Un jardin philosophe, 50 Rue Mgr Médard Barth, 67530 Bœrsch, France', 'Un jardin philosophe, 50 Rue Mgr Médard Barth, 67530 Bœrsch, France', 'Un jardin philosophe', '', 'Bœrsch', '67052', '67', 44.0, 48.476095000000, 7.4400270000000, '[]', 'Jardin contemporain,Jardin privé', 2012, 'Situé aux abords de l’enceinte médiévale de la ville, ce jardin privé d’un hectare s’inscrit dans un riche contexte historique et paysager. Aménagé au XIXe siècle en jardin d’agrément, il fut le berceau d’une famille d’artistes qui a contribué à faire rayonner le patrimoine culturel alsacien. Ses propriétaires actuels s’attachent à le restaurer en mettant en valeur les éléments variés qui le caractérisent. Ils conçoivent sa visite comme une initiation à l’esprit du lieu, à l’art et à la philosophie des jardins, et proposent une promenade scandée par des moments de lecture et de réflexion. Le cheminement entre nature et culture mène de jardins clos de treillages et de buis jusqu’au pied d’arbres spectaculaires, d’un vaste verger quadrillé d’allées-perspectives vers un petit bois, longe le rempart médiéval, remonte le cours du ruisseau serpentin...', '', 'JARD_67052_0001', 'MHR_44_JR0001', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:27:54', '48.476095, 7.440027'),
('Potager fleuri du château de Lantilly', 21140, 'Bourgogne-Franche-Comté', 'Côte-d\'Or', '1 Chem. de Lantilly, 21140 Lantilly, France', '1 Chem. de Lantilly, 21140 Lantilly, France', '1 Chem. de Lantilly', '', 'Lantilly', '21341', '21', 27.0, 47.544241000000, 4.3980560000000, '[\"https://www.chateau-lantilly.fr\", \"https://www.facebook.com/Lantilly/\"]', 'Parc paysager,Jardin contemporain,Jardin vivrier,Jardin privé', 2004, 'Parc à l\'anglaise planté au XIXe siècle avec potager fleuri.', '', 'JARD_21341_0001', 'MHR_27_JR0008', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:16', '47.544241, 4.398056'),
('Parc et jardins du château de La Roche-Jagu', 22260, 'Bretagne', 'Côtes-d\'Armor', 'Château de la Roche-Jagu, 22260 Ploëzal, France', 'Château de la Roche-Jagu, 22260 Ploëzal, France', 'Château de la Roche-Jagu', '', 'Ploëzal', '22204', '22', 53.0, 48.733202000000, -3.1510343000000, '[\"http://www.larochejagu.fr\", \"https://www.facebook.com/larochejagu\", \"https://twitter.com/rochejagu22\", \"https://www.instagram.com/la_roche_jagu/\"]', 'Jardin d\'inspiration médiévale,Parc paysager,Jardin contemporain,Jardin public', 2005, 'Parc départemental contemporain aménagé au cours des années 1990 par l’architecte paysagiste Bertrand Paulet sur le site escarpé d’une forteresse médiévale dominant une boucle du Trieux. Etagé en terrasses offrant de nombreux points de vue, le parc s’organise autour de l’eau, domestiquée en une succession de bassins reliés par des goulettes. Plus près du château, les jardins offrent de petits espaces consacrés aux fleurs, aux simples et aux légumes. Ouverture toute l’année, ateliers nature, programmation culturelle (74 ha).', '', 'JARD_22204_0001', 'MHR_53_JR0005', '[]', '[]', '', '2020-06-08 09:24:00', '2022-10-07 22:46:51', '48.733202, -3.1510343'),
('Parc et jardin de l\'Abrègement', 16700, 'Nouvelle-Aquitaine', 'Charente', 'L\'Abrègement, 16700 Bioussac, France', 'L\'Abrègement, 16700 Bioussac, France', 'L\'Abrègement', '', 'Bioussac', '16002', '16', 75.0, 46.028543000000, 0.2799060000000, '[]', 'Parc paysager,Jardin contemporain,Jardin de collection,Jardin privé', 2008, 'Pour recréer le parc dévasté par la tempête de 1999, les artistes contemporains Andy Goldsworthy, Antony Gormley, Christian Lapie et Joël Shapiro ont utilisé avec imagination bois courbes, troncs de chêne et de séquoia et autres bois sinistrés pour réaliser leurs sculptures originales. À l\'orée de la forêt, une querceraie présente une jeune collection de plus de 170 variétés de chênes comprenant 118 espèces et 20 hybrides. Le potager, clos de mur, abrite une tonnelle de calebasses, une profusion de fleurs et un cours d\'eau.', '', 'JARD_16044_0001', 'MHR_75_JR0002', '[]', '[]', 'monument historique', '', '2022-11-24 15:14:41', '46.028543, 0.279906'),
('Jardin alpin du Lautaret', 5480, 'Provence-Alpes-Côte d\'Azur', 'Hautes-Alpes', 'LE MONETIER-L B - Col du Lautaret - LE MONETIER-LES, 05480 Villar-d\'Arène, France', 'LE MONETIER-L B - Col du Lautaret - LE MONETIER-LES, 05480 Villar-d\'Arène, France', 'LE MONETIER-L B - Col du Lautaret - LE MONETIER-LES', '', 'Villar-d\'Arène', '5181', '5', 93.0, 45.034782000000, 6.4049300000000, '[\"https://www.jardinalpindulautaret.fr\", \"https://www.facebook.com/jardinalpinLautaret/\", \"https://twitter.com/GardenSajf\"]', 'Jardin de collection,Jardin public', 2005, 'Crée en 1899, le Jardin Botanique Alpin du Lautaret est le témoin d’une passion centenaire de l’Université de Grenoble pour la flore alpine. La richesse des collections et l’aménagement en rocailles intégrées au paysage font de ce jardin d’altitude l’un des plus beaux d’Europe.', '', 'JARD_05181_0001', 'MHR_93_JR0023', '[]', '[]', '', '', '2022-07-22 10:28:10', '45.034782, 6.40493'),
('Le Grand Jardin', 52300, 'Grand Est', 'Haute-Marne', '5 Av. de la Marne, 52300 Joinville, France', '5 Av. de la Marne, 52300 Joinville, France', '5 Av. de la Marne', '', 'Joinville', '52250', '52', 44.0, 48.446693000000, 5.1412780000000, '[\"https://haute-marne.fr/culture/chateau-du-grand-jardin/\"]', 'Jardin régulier,Jardin public', 2008, 'Les entrelacs et les topiaires de buis, les 365 arbres fruitiers, le labyrinthe, les carrés bouquetier et médicinal proposent une évocation du jardin Renaissance de Claude de Grand-Est. Remis en valeur en 2003, le parc pittoresque recèle plusieurs essences rares dont des muscadiers, un frêne panaché, des cyprès chauves,… ; le pourtour de sa muraille est occupé par une collection de 150 espèces et variétés de buis qui a été agréée par le Conservatoire des collections végétales spécialisées.', '', 'JARD_52250_0001', 'MHR_44_JR0021', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-07-22 10:28:09', '48.446693, 5.141278'),
('Jardin de Boissonna', 47120, 'Nouvelle-Aquitaine', 'Lot-et-Garonne', '88 Imp. Grand Bois, 47120 Baleyssagues, France', '88 Imp. Grand Bois, 47120 Baleyssagues, France', '88 Imp. Grand Bois', '', 'Baleyssagues', '47020', '47', 75.0, 44.696929000000, 0.1432050000000, '[\"http://www.jardindeboissonna.com\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2009, 'Jardin intimiste composé de jardins à thèmes dont les massifs informels proposent une grande variété d’essences végétales et de roses.', '', 'JARD_47020_0001', 'MHR_75_JR0029', '[]', '[]', '', '', '2022-07-22 10:28:05', '44.696929, 0.143205'),
('Jardins du manoir du Grand Courtoiseau', 45220, 'Centre-Val de Loire', 'Loiret', 'Le Grand Courtoiseau, 45220 Triguères, France', 'Le Grand Courtoiseau, 45220 Triguères, France', 'Le Grand Courtoiseau', '', 'Triguères', '45083', '45', 24.0, 47.938656000000, 2.9661300000000, '[\"http://www.grand-courtoiseau.fr/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Autour d\'un manoir du XVIIIe siècle (ISMH), jardins de plates-bandes de roses anciennes, vivaces, bulbes et arbustes rares, bordées de buis et ceinturées de topiaires d\'ifs. Parc, exceptionnelle avenue de vénérables tilleuls, douves paysagères, fontaines, statues et éléments architecturaux anciens.Fragrances et murmures de l\'eau accompagneront vos pas.', '', 'JARD_45329_0001', 'MHR_24_JR0028', '[]', '[]', '', '2020-06-08 09:25:00', '2022-10-11 21:32:13', '47.938656, 2.96613'),
('Parc de Courson', 91680, 'Île-de-France', 'Essonne', '1 Château de Courson, 91680 Courson-Monteloup, France', '1 Château de Courson, 91680 Courson-Monteloup, France', '1 Château de Courson', '', 'Courson-Monteloup', '91186', '91', 11.0, 48.600216000000, 2.1473220000000, '[\"http://www.domaine-de-courson.fr\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2004, 'Parc romantique, fruit du travail des meilleurs paysagistes des XIXe et XXe siècles (Louis-Martin Berthault, Denis et Eugène Bühler, Timothy Vaughan, Ernest de Caraman, Louis Benech), où se marient en toute saison botanique et esthétique, ce parc invite à la promenade dans une étonnante ambiance de paix et de sérénité. Floraisons d\'été (roses, hortensias, asters, azalées, rhododendrons et couleurs d\'automne).', '', 'JARD_91186_0001', 'MHR_11_JR0003', '[]', '[]', 'monument historique', '', '2022-07-22 10:27:59', '48.600216, 2.147322'),
('Jardin botanique de La Presle', 51480, 'Grand Est', 'Marne', '90 D22E1, 51480 Nanteuil-la-Forêt, France', '90 D22E1, 51480 Nanteuil-la-Forêt, France', '90 D22E1', '', 'Nanteuil-la-Forêt', '51393', '51', 44.0, 49.152502000000, 3.9253110000000, '[\"http://www.jardin-brochetlanvin.com\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2006, 'Jardin de pépiniéristes collectionneurs devenu en 1995 site conservatoire avec ses deux collections nationales de saules et de spirées, puis en 2001 jardin botanique et enfin centre de formation horticole pour tout public. La Presle poursuit son dynamisme créatif avec les interventions d’un jeune paysagiste.', '', 'JARD_51393_0001', 'MHR_44_JR0028', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:11', '49.152502, 3.925311'),
('Parc arboretum de Neuvic d\'Ussel', 19160, 'Nouvelle-Aquitaine', 'Corrèze', '10 Pl. de la Mairie, 19160 Neuvic, France', '10 Pl. de la Mairie, 19160 Neuvic, France', '10 Pl. de la Mairie', '', 'Neuvic', '19148', '19', 75.0, 45.383199000000, 2.2721960000000, '[\"http://www.larboretum-neuvicdussel.com\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2008, 'Label Qualité Hérault', '', 'JARD_19148_0001', 'MHR_75_JR0001', '[]', '[]', 'monument historique', '2020-12-11 13:15:19', '2022-07-22 10:28:16', '45.383199, 2.272196'),
('Jardin de Mazet', 30170, 'Occitanie', 'Gard', 'Monoblet, 30170 Monoblet, France', 'Monoblet, 30170 Monoblet, France', 'Monoblet', '', 'Monoblet', '30058', '30', 76.0, 43.999581000000, 3.8876200000000, '[\"http://www.mariedemazet.com\", \"https://www.instagram.com/mariedemazet/\"]', 'Jardin de collection,Jardin vivrier,Jardin privé', 2012, 'Un authentique \"Jardin des Simples\" de 10 hectares s\'étend non loin d’une maison de maître du XVIIe siècle sur une succession de terrasses situées à 450 m d\'altitude sur les contreforts des Cévennes.\r\n Dans les Jardins de Mazet, plus de 40 variétés de plantes aux vertus médicinales sont cultivées en mode biologique. La fondatrice du domaine, Marie d\'Hennezel, veille, depuis 20 ans, dans son exploitation, à associer beauté et santé, guidée par un profond sens esthétique et le respect de la nature. Cette promenade balisée de panneaux explicatifs s’offre à ceux qui sont à la recherche d\'authenticité et de sérénité, aux curieux de la Nature bienfaisante.', '', 'JARD_30172_0001', 'MHR_76_JR0004', '[]', '[]', '', '', '2022-12-07 16:28:31', '43.999581, 3.88762');
INSERT INTO `liste_des_jardins_remarquables` (`Nom du jardin`, `Code Postal`, `Region`, `Departement`, `Adresse complete`, `Adresse de l’entree du public`, `Numero et libelle de la voie`, `Complement d'adresse`, `Commune`, `Code INSEE`, `Code INSEE Departement`, `Code INSEE Region`, `Latitude`, `Longitude`, `Site Internet et autres liens`, `Types`, `Annee d'obtention`, `Description`, `Auteur / Nom de l'illustre`, `Identifiant DEPS`, `Identifiant origine`, `Accessible au public`, `Conditions d’ouverture`, `Equipement Précision`, `Date de création`, `Date de MAJ`, `coordonnees_geographiques`) VALUES
('Jardins du château de Losmonerie', 87700, 'Nouvelle-Aquitaine', 'Haute-Vienne', '', 'Route de Losmonerie, 87700 Aixe-sur-Vienne, France', 'Route de Losmonerie', '', 'Aixe-sur-Vienne', '87001', '87', 75.0, 45.804563000000, 1.1250620000000, '[\"www.losmonerie.fr\"]', 'Jardin régulier,Jardin privé,Jardin vivrier', 2023, 'Trois jardins s’appuyant sur des tracés anciens du xvie siècle sont proposés à la visite. Le premier, proche de la bâtisse, se veut formel et propose des massifs fleuris. Le second éveille les papilles avec plus de 100 variétés de framboisiers et de nombreux arbres fruitiers étonnants pour la région. Dans le dernier jardin, dit « sauvage », les graines voyagent et s’installent naturellement. Une cabane en osier sec et vivant, créée par Emmanuel Puybonnieux et le « boudoir du terroir », œuvre d’art de l’artiste suisse Simon Beer complètent la visite de ce lieu qui offre une vue imprenable sur la Vienne.', '', '', '', '[\"ouvert\"]', '[\"saisonnière\", \"de jour\"]', '', '2023-03-31 13:53:51', '2023-04-12 17:38:05', '45.804563, 1.125062'),
('Jardin du château de Talcy', 41370, 'Centre-Val de Loire', 'Loir-et-Cher', '', '18 Rue du Château, 41370 Talcy, France', '18 Rue du Château', '', 'Talcy', '41027', '41', 24.0, 47.769313000000, 1.4446450000000, '[\"https://www.chateau-talcy.fr/\"]', 'Jardin régulier,Jardin vivrier,Jardin de collection,Jardin contemporain', 2022, 'Situé en Beauce, non loin de Blois, au cœur d’un terroir essentiellement céréalier, le château de Talcy, véritable « maison des champs » est prolongé par un jardin de 7 ha, clos de murs, à l’exception de son bois. De trame régulière, il suit une perspective principale axée nord/sud et est divisé en quatre parties : les cours, le parterre, le jardin nourricier et le bois.', '', '', '', '', '', '', '', '', '47.769313, 1.444645'),
('Pavillon de Galon', 84160, 'Provence-Alpes-Côte d\'Azur', 'Vaucluse', '151 Chem. de Galon, 84160 Cucuron, France', '151 Chem. de Galon, 84160 Cucuron, France', '151 Chem. de Galon', '', 'Cucuron', '84042', '84', 93.0, 43.774865000000, 5.4451660000000, '[\"http://www.pavillondegalon.com\", \"https://www.facebook.com/pavillondegalon\", \"https://www.instagram.com/lepavillondegalon/\"]', 'Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2009, 'Jardin contemporain à la française, bassins, pavillon de chasse, conservatoire de plantes', '', 'JARD_84042_0001', 'MHR_93_JR0039', '[]', '[]', '', '2020-06-08 09:23:00', '2022-07-22 10:28:11', '43.774865, 5.445166'),
('Parc du château d\'Arcelot', 21310, 'Bourgogne-Franche-Comté', 'Côte-d\'Or', '2 Rue du Colombier, 21310 Arceau, France', '2 Rue du Colombier, 21310 Arceau, France', '2 Rue du Colombier', '', 'Arceau', '21016', '21', 27.0, 47.368170000000, 5.1925690000000, '[\"http://www.arcelot.com\", \"https://www.facebook.com/chateau.arcelot\", \"https://www.instagram.com/chateauarcelot/\"]', 'Parc paysager,Jardin vivrier,Jardin privé', 2004, 'A l\'origine, vaste jardin à la française, le parc fut complètement transformé vers 1805 par le paysagiste Jean-Marie Morel. On le considère comme le parc le mieux préservé du premier théoricien des jardins. Il comporte des arbres rares et un étang de 7 hectares.', '', 'JARD_21016_0001', 'MHR_27_JR0005', '[]', '[]', 'monument historique', '2020-12-11 13:15:50', '2022-07-22 10:28:16', '47.36817, 5.192569'),
('Jardin de Pomone', 17400, 'Nouvelle-Aquitaine', 'Charente-Maritime', '2 Rue d\'Angély, 17400 Essouvert, France', '2 Rue d\'Angély, 17400 Essouvert, France', '2 Rue d\'Angély', '', 'Essouvert', '17277', '17', 75.0, 45.985145000000, -0.5365730000000, '[\"http://www.lejardindepomone.fr\"]', 'Jardin contemporain,Jardin de collection,Jardin privé', 2011, 'À travers massifs colorés, fontaines et pergolas, le visiteur est invité à découvrir l\'ensemble des fruits comestibles des climats tempérés et méditerranéens. Pomone, déesse des fruits et des vergers nous rappelle le lien privilégié tissé entre l\'homme et le fruit au fil du temps, de la symbolique, de la géographie et de la botanique. Consommé au néolithique ou fruit du futur, venant de Chine ou d\'Asie Mineure, demeuré sauvage ou domestiqué, le fruit nous invite à un fabuleux voyage.', '', 'JARD_17277_0001', 'MHR_75_JR0042', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:05', '45.985145, -0.536573'),
('La ferme du Mont des Récollets', 59670, 'Hauts-de-France', 'Nord', '1793 Rte de Steenvoorde, 59670 Cassel, France', '1793 Rte de Steenvoorde, 59670 Cassel, France', '1793 Rte de Steenvoorde', '', 'Cassel', '59135', '59', 32.0, 50.802519000000, 2.5042170000000, '[\"https://www.parcsetjardins.fr/jardins/626-jardins-du-mont-des-recollets\"]', 'Jardin contemporain,Jardin vivrier,Jardin privé', 2006, 'Le jardin, créé dans les années 1990, prend son inspiration dans ce que peut représenter ou être un jardin et son environnement dans la Flandre. La retranscription a été d\'autant de \"chambres extérieures\" qui pourraient entrer dans l\'esprit d\'un jardin flamand. En périphérie du jardin, la quasi-totalité des espèces plantées est régionale se retrouvant à l\'état spontané dans la nature. Nous laissons prospérer les espèces en liberté dans un but de redécouverte de nos écosystèmes: ainsi se sont installées cardères, cardamines et véroniques des prés, jacinthes des bois, orchidées sauvages... La dominante arbustive plantée est noisetier, érable, viorne, fusain, aubépine et prunellier. Au coeur même du jardin : inspiration de 3 styles de jardins propres à la Flandre: jardin de la Renaissance flamande, jardin traditionnel (XIXe, début XXe) et jardin contemporain', '', 'JARD_59135_0001', 'MHR_32_JR0001', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:27:58', '50.802519, 2.504217'),
('Jardin anglais', 70000, 'Bourgogne-Franche-Comté', 'Haute-Saône', '4B Rue Pierre de Coubertin, 70000 Vesoul, France', '4B Rue Pierre de Coubertin, 70000 Vesoul, France', '4B Rue Pierre de Coubertin', '', 'Vesoul', '70550', '70', 27.0, 47.622308000000, 6.1638700000000, '[\"http://vesoul.fr/\"]', 'Parc paysager,Jardin public', 2015, 'Le Jardin anglais est un jardin public situé dans le quartier du Stade à Vesoul, préfecture du département de la Haute-Saône. Aménagé en 1863 par l\'architecte paysagiste Brice Michel, l\'espace vert subit plusieurs modifications depuis cette dernière date jusqu\'à ce qu\'il soit dessiné en jardin à l\'anglaise en 1976.', '', 'JARD_70550_0001', 'MHR_27_JR0027', '[]', '[]', '', '2020-12-11 13:14:34', '2022-07-22 10:27:53', '47.622308, 6.16387'),
('Jardin du château de Val Joanis', 84120, 'Provence-Alpes-Côte d\'Azur', 'Vaucluse', '2404 Route de Villelaure', '2404 Route de Villelaure, 84120 Pertuis, France', '2404 Route de Villelaure', '', 'Pertuis', '84010', '84', 93.0, 43.690623000000, 5.5010970000000, '[\"http://www.val-joanis.com\"]', 'Jardin régulier,Jardin vivrier,Jardin privé', 2005, 'Jardin constitué de 3 terrasses : un potager d’inspiration XVIIIe siècle, un jardin de rosiers et fruitiers palissés, un jardin pour arbres d’ornement. Prix Jardin 2008.', '', 'JARD_84089_0001', 'MHR_93_JR0041', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-08 09:25:00', '2022-12-16 15:56:46', '43.690623, 5.501097'),
('Parc du manoir de la Javelière', 45340, 'Centre-Val de Loire', 'Loiret', '10 Rte de la Javelière, 45340 Montbarrois, France', '10 Rte de la Javelière, 45340 Montbarrois, France', '10 Rte de la Javelière', '', 'Montbarrois', '45209', '45', 24.0, 48.043911000000, 2.4088280000000, '[\"http://www.lajaveliere.fr\"]', 'Jardin régulier,Parc paysager,Jardin contemporain,Jardin de collection,Jardin privé', 2012, 'Les jardins de la Javelière présentent des décors très variés : une roseraie moderne, un parc à l\'anglaise agrémenté de nombreux arbres et arbustes de collection, un jardin d\'inspiration italienne, un décor japonisant, des topiaires, un jardin potager... Un sentier bordé de roses anciennes et de lavandes sinue autour d\'un étang aux eaux turquoises. Le \'Rosarium\" possède une importante collection de rosiers botaniques riche de 300 taxons et agréée par le CCVS (Conservatoire des Collections Végétales Spécialisées).', '', 'JARD_45209_0001', 'MHR_24_JR0025', '[]', '[]', '', '2020-12-11 13:15:47', '2022-07-22 10:27:51', '48.043911, 2.408828'),
('Arboretum des Pouyouleix', 24800, 'Nouvelle-Aquitaine', 'Dordogne', '124 Les Pouyouleix, 24800 Saint-Jory-de-Chalais, France', '124 Les Pouyouleix, 24800 Saint-Jory-de-Chalais, France', '124 Les Pouyouleix', '', 'Saint-Jory-de-Chalais', '24095', '24', 75.0, 45.473168300000, 0.8883237000000, '[\"https://arboretumpouyouleix.com/arboretum-des-pouyouleix\"]', 'Jardin de collection,Jardin privé', 2021, 'Situé aux confins de la Dordogne, l’arboretum des Pouyouleix est un parc écologique de 25 hectares dans lequel une collection d’arbres est venue humblement compléter l’existant et s’adapter aux conditions offertes naturellement par le site. Guidés par le désir de présenter une collection du genre Quercus, les propriétaires parcourent le monde à la recherche des graines, poursuivant modestement la conquête et la connaissance botanique, tout en assurant l’avenir de certaines espèces menacées. La diversité des feuillages, des troncs et des fruits complète la visite de ce site.', '', '', '', '[]', '[]', '', '2022-09-08 17:00:04', '2022-09-08 17:00:04', '45.4731683, 0.8883237'),
('Parc du château du Touvet', 38660, 'Auvergne-Rhône-Alpes', 'Isère', '1 Chemin des Chadeaux 38660 Le Touvet', '1 Chemin des Chadeaux 38660 Le Touvet', '1 Chemin des Chadeaux', '', 'Le Touvet', '38214', '38', 84.0, 45.342420000000, 5.9381940000000, '[\"http://www.chateaudutouvet.com\", \"https://www.facebook.com/Jardins-Ch%C3%A2teau-du-Touvet-152706664760316\"]', 'Jardin régulier,Jardin privé', 2004, 'A l’ombre du château, les jardins aménagés en 1750 sur 5 hectares, s’organisent autour d’un remarquable escalier d’eau à l’italienne alimenté par les eaux vives du massif de Chartreuse. Longues terrasses, buis et ifs savamment taillés, jardin clos, roseraie, bassins et fontaines ponctuent l’ensemble avec art.', '', 'JARD_38511_0001', 'MHR_84_JR0025', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-11-28 16:54:58', '45.34242, 5.938194'),
('Parc du château de Vendeuvre', 14170, 'Normandie', 'Calvados', '9 Le Château, 14170 Vendeuvre, France', '9 Le Château, 14170 Vendeuvre, France', '9 Le Château', '', 'Vendeuvre', '14735', '14', 28.0, 48.987441500000, -0.0785600000000, '[\"https://www.parcsetjardins.fr/jardins/65-parc-et-jardins-du-chateau-de-vendeuvre\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Trois merveilleux jardins se succèdent à Vendeuvre dans un parc immense.\r\n Au milieu d\'une végétation luxuriante, vous découvrirez des jeux d\'eau \"surprises\" facétieux dissimulés parmi les bosquets et les constructions de fantaisie : temple, kiosque, cascade, pavillons, labyrinthe, pont chinois, grotte de coquillages ...\r\n Château meublé du XVIIIe siècle Collection de meubles de maîtrise minuscules, collection de niches à chiens du XVIIe au XIXe siècles.', '', 'JARD_14735_0001', 'MHR_28_JR0008', '[]', '[]', '', '', '2022-07-22 10:28:15', '48.9874415, -0.07856'),
('Mascarin Jardin botanique de la Réunion', 97436, 'Réunion', 'Réunion', '2 Rue du Pere Georges, 97436 Saint-Leu, France', '2 Rue du Pere Georges, 97436 Saint-Leu, France', '2 Rue du Pere Georges', '', 'Saint-Leu', '97413', '974', 4.0, -21.137577200000, 55.2953971000000, '[\"https://www.departement974.fr/mascarin-jardin-botanique\"]', 'Jardin de collection,Jardin vivrier,Jardin public', 2019, 'A l\'origine, ce domaine faisait partie de la vaste propriété agricole (660 ha) de Sosthènes d\'Armand de Chateauvieux et de sa descendance, qui vécurent sur ce site depuis 1857. Aujourd\'hui, l\'immense maison et les dépendances abritent Mascarin Jardin Botanique de La Réunion qui présente 8 collections botaniques différentes et qui a une double mission : la sensibilisation et l\'éducation des publics à la préservation des milieux naturels et de la flore indigène locale et la transmission des savoirs culturels réunionnais.', '', 'JARD_97413_0001', 'MHR_04_JR0002', '[\"ouvert\"]', '[]', '', '2020-06-09 09:16:00', '2022-12-26 18:06:46', '-21.1375772, 55.2953971'),
('Parc Borély', 13008, 'Provence-Alpes-Côte d\'Azur', 'Bouches-du-Rhône', '394 Av. du Prado, 13008 Marseille, France', '394 Av. du Prado, 13008 Marseille, France', '394 Av. du Prado', '', 'Marseille', '13055', '13', 93.0, 43.269435000000, 5.3860960000000, '[\"http://monumentsdemarseille.com/parc-borely\"]', 'Jardin régulier,Parc paysager,Jardin public', 2005, 'Le plus célèbre des parcs marseillais sur 17 hectares, avec jardin à la française, parc à l’anglaise et plan d’eau sur lequel on peut canoter. Une cascade en rocaille sert d’écrin à \"l’homme aux oiseaux\" de Folon. Jardin botanique avec des collections de plantes médicinales, grimpantes, succulentes, palmiers, serre pour flore d’Afrique du Sud, jardin traditionnel chinois offert par la ville de Shanghai.', '', 'JARD_13208_0001', 'MHR_93_JR0020', '[]', '[]', 'monument historique', '2022-03-09 12:54:13', '2022-07-22 10:28:20', '43.269435, 5.386096'),
('Potager du château Colbert', 49360, 'Pays de la Loire', 'Maine-et-Loire', 'La Maison Neuve, 49360 Maulevrier, France', 'La Maison Neuve, 49360 Maulevrier, France', 'La Maison Neuve', '', 'Maulevrier', '49192', '49', 52.0, 47.010670000000, -0.7864800000000, '[\"http://www.chateaucolbert.com\"]', 'Jardin contemporain,Jardin vivrier,Jardin privé', 2018, 'Le potager de 8 000 m² a été créé par les Colbert en 1768. Il a ensuite été restauré entre 1820 et 1840. Lorsque la lignée des Colbert s’éteint, et que les Bergère de riches industriels choletais se portent acquéreurs en 1893, il est en pleine splendeur. Ils feront eux mêmes de nombreux aménagements et créeront en 1903 une nouvelle serre dont on peut admirer une partie restaurée aujourd’hui. Jusqu’à la seconde guerre mondiale il est un chef d’oeuvre de tenue et de production. De 1946 à 1977 le domaine est confié à des congrégations religieuses qui après avoir tenté de le transformer le laisseront à l’abandon. Cet endroit tant soigné et aimé restera ainsi dénaturé pendant près de 50 ans jusqu’a l’arrivée des actuels propriétaires qui décideront en 2011 de le restaurer dans sa totalité.', '', 'JARD_49192_0001', 'MHR_52_JR0019', '[\"ouvert\"]', '[\"saisonnière\", \"de jour\"]', '', '2020-12-11 13:14:15', '2022-12-21 12:23:27', '47.01067, -0.78648'),
('Parc des Roches', 52150, 'Grand Est', 'Haute-Marne', '21 Gonaincourt, 52150 Bourmont-entre-Meuse-et-Mouzon, France', '21 Gonaincourt, 52150 Bourmont-entre-Meuse-et-Mouzon, France', '21 Gonaincourt', '', 'Bourmont-entre-Meuse-et-Mouzon', '52064', '52', 44.0, 48.211996000000, 5.5979420000000, '[\"https://www.societehistoriquearcheologiquedebourmont.com/le-parc-des-roches\"]', 'Parc paysager,Jardin public', 2012, 'Situé en contrebas de la promenade du Côna, ce parc témoigne du goût romantique pour les fausses ruines, habilement combinées ici à la falaise calcaire qui domine l\'ensemble.', '', 'JARD_52064_0001', 'MHR_44_JR0020', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:09', '48.211996, 5.597942'),
('Jardins Ephrussi de Rothschild', 6230, 'Provence-Alpes-Côte d\'Azur', 'Alpes-Maritimes', '6 Av. Ephrussi de Rothschild, 06230 Saint-Jean-Cap-Ferrat, France', '6 Av. Ephrussi de Rothschild, 06230 Saint-Jean-Cap-Ferrat, France', '6 Av. Ephrussi de Rothschild', '', 'Saint-Jean-Cap-Ferrat', '6121', '6', 93.0, 43.695847000000, 7.3294560000000, '[\"http://villa-ephrussi.com\", \"https://www.facebook.com/villaephrussi\"]', 'Jardin régulier,Jardin privé', 2005, 'Plusieurs jardins à thème à la française, florentin, japonais, espagnol, lapidaire, exotique, provençal et Sèvres, ornés de patios, de cascades et de bassins. Statuaire, roseraie, palais Belle Epoque. \r\n Animations en cours d’année : 3e fête des roses (10-12 mai).', '', 'JARD_06121_0001', 'MHR_93_JR0015', '[]', '[]', 'monument historique', '2020-12-11 13:16:49', '2022-07-22 10:28:20', '43.695847, 7.329456'),
('Jardin de Beauvallon', 97100, 'Guadeloupe', 'Guadeloupe', '156 Chem. de Beauvallon, Basse-Terre 97100', '156 Chem. de Beauvallon, 97100 Basse-Terre, France', '156 Chem. de Beauvallon', '', 'Basse-Terre', '97105', '971', 1.0, 16.005535000000, -61.7272030000000, '[\"https://zoom-guadeloupe.fr/visiter-sur-basse-terre/jardin-de-beauvallon\"]', 'Parc paysager,Jardin privé', 2013, 'Situé sur les hauteurs de Basse-Terre, le jardin est situé sur les terres de l\'ancienne habitation Mont Bazin, attestée dès 1814, à la jonction entre espace urbain et espace naturel. Axé sur l\'agrément, il présente environ 450 espèces de plantes et d’arbres des zones tropicales, et une belle collection de palmiers. Grand carbet et un espace d\'accueil-boutique.', '', 'JARD_97105_0001', 'MHR_01_JR0001', '[\"ouvert\"]', '[\"de jour\"]', '', '', '2023-01-08 00:02:43', '16.005535, -61.727203'),
('Jardins du Gué', 79390, 'Nouvelle-Aquitaine', 'Deux-Sèvres', 'Les Jardins du Gué, Gué de Flais, 79390 Lhoumois, France', 'Les Jardins du Gué, Gué de Flais, 79390 Lhoumois, France', 'Les Jardins du Gué', '', 'Lhoumois', '79149', '79', 75.0, 46.710902000000, -0.1450290000000, '[\"https://www.jardinsdugue.eu\"]', 'Parc paysager,Jardin de collection,Jardin privé', 2013, 'Ce jardin a obtenu le label Jardin Remarquable et le Grand Prix du Concours National des Jardins Potagers de France en 2013. Outre le jardin Gourmand, le visiteur pourra déambuler et découvrir le Jardin des Voyageurs, le Jardin de l’Amour, le Jardin des Succulentes, le Jardin des Arts, le Jardin des Braves pour finir par le Jardin du Temps. Une promenade inoubliable aux bords de la rivière.', '', 'JARD_79149_0001', 'MHR_75_JR0045', '[]', '[]', '', '2020-09-15 18:18:00', '2022-07-22 10:28:06', '46.710902, -0.145029'),
('Les jardins secrets', 74150, 'Auvergne-Rhône-Alpes', 'Haute-Savoie', '1561 Rte de Lagnat, 74150 Vaulx, France', '1561 Rte de Lagnat, 74150 Vaulx, France', '1561 Rte de Lagnat', '', 'Vaulx', '74292', '74', 84.0, 45.918531000000, 5.9862750000000, '[\"https://www.jardins-secrets.com\", \"https://www.facebook.com/jardins.secrets74/\", \"https://www.instagram.com/jardins.secrets/\"]', 'Jardin contemporain,Jardin privé', 2019, 'Situés en Haute-Savoie, entre Annecy et Aix les Bains, les Jardins Secrets offrent une flânerie dépaysante et conviviale. Ces jardins sont l\'oeuvre d\'une vie. Nicole et Alain Moumen ont intégré́ dans leurs jardins des matériaux habituellement peu utilisés par les paysagistes, en les détournant souvent de leur fonction habituelle : bois, galets, mortier de chaux, cuivre, verre et eau. Fleurs et plantes s\'épanouissent librement et subliment une architecture audacieuse. Fruit d\'une création imaginative, jardins, salons, galeries, patios, fontaines se succèdent et composent sur 7000 m2 une mosaïque aux inspirations variées au coeur d\'un univers unique et authentique', '', 'JARD_74292_0001', 'MHR_84_JR0032', '[\"ouvert\"]', '[\"saisonnière\", \"de jour\"]', '', '2020-06-08 09:25:00', '2022-12-15 17:12:10', '45.918531, 5.986275'),
('Parc de la Tête d\'Or', 69006, 'Auvergne-Rhône-Alpes', 'Rhône', 'Place du Général Leclerc, 69006 Lyon, France', 'Place du Général Leclerc, 69006 Lyon, France', 'Place du Général Leclerc', '', 'Lyon', '69123', '69', 84.0, 45.777125700000, 4.8448666000000, '[\"https://www.lyon.fr\", \"https://www.facebook.com/Parc-de-la-T%C3%AAte-dor-29597219628\"]', 'Parc paysager,Jardin de collection,Jardin public', 2006, 'Parc de la ville de Lyon de 105 hectares créé par les frères Bühler en 1857. L\'entrée principale Porte des Enfants du Rhône ouvre sur la perspective d\'un lac de 16 hectares, centre de la composition paysagère. Il est orné de deux roseraies (plus de 400 variétés), d\'arbres remarquables et d\'une importante statuaire. Le parc comprend également un jardin botanique avec ses grandes et petites serres et sa roseraie qui retrace l\'histoire de la rose, un jardin zoologique dont une partie a été réaménagée en Plaine africaine en 2005.', '', 'JARD_69381_0002', 'MHR_84_JR0016', '[]', '[]', '', '2022-03-09 12:54:46', '2022-10-06 18:20:23', '45.7771257, 4.8448666'),
('Parc du château de Merville', 31330, 'Occitanie', 'Haute-Garonne', '4 Pl. du Château, 31330 Merville, France', '4 Pl. du Château, 31330 Merville, France', '4 Pl. du Château', '', 'Merville', '31341', '31', 76.0, 43.719129000000, 1.3004010000000, '[\"http://labyrinthedemerville.com\", \"https://www.facebook.com/labyrinthedemerville/\", \"https://www.instagram.com/chateaudemerville/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Construit au milieu du XVIIIe siècle par le marquis de Chalvert, sénéchal de Toulouse, le château de Merville est une belle et sobre bâtisse très représentative de l\'architecture de l\'époque dans le Midi toulousain. Son par privé de 25 ha du XVIIIe siècle classé monument historique intègre un étonnant jardin de buis de la même époque et étroitement lié à l\'édifice. Allées de hauts buis, perspectives, ronds-points, bassin, salles de verdure, labyrinthe, jardins secrets. Il est ouvert aujourd\'hui grâce à un important programme de restauration entrepris depuis plusieurs années par les propriétaires actuels habitant le château, et descendants directs du marquis de Chalvet.\r\n Bordé à l\'est par une grande perspective de pelouse, avec un bassin central, le jardin de buis représentant une surface de 5 ha se transforme au printemps en \"labyrinthe des merveilles\".', '', 'JARD_31341_0001', 'MHR_76_JR0022', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-10-07 22:00:48', '43.719129, 1.300401'),
('Jardin de l’Isola / U giardinu di l’Isuli', 20144, 'Corse', 'Corse-du-Sud', 'Costa Di Ventura, 20144 Zonza, France', 'Costa Di Ventura, 20144 Zonza, France', 'Costa Di Ventura', '', 'Zonza', '2A362', '2A', 94.0, 41.665336000000, 9.3626292000000, '[\"http://www.ugiardinudilisuli.fr\", \"https://www.instagram.com/le_jardin_de_marie/\"]', 'Jardin de collection', 2015, 'Créé en 1998, ce jardin aux espèces subtropicales et tropicales (plus de de 1 400 espèces) est composé de sept îlots de verdure consacrés chacun à une zone géographique particulière. Le terrain, de près d’un hectare, a été choisi pour son exposition et ses points de vue sur la mer Méditerranée. La première zone met en valeur les plantes d\'Australie et de Nouvelle Zélande, puis vient la zone de l\'Asie du Sud-Est, puis celle de Nouvelle-Calédonie et des îles du Pacifique, enfin celle de Macaronésie (Iles Canaries, Madère et côte atlantique du Maroc). En face, l\'Amérique Centrale et du Sud voisine avec l\'Afrique australe où les plantes d’Afrique du Sud et de Madagascar sont à l’honneur. Le haut du terrain est lui consacré à la flore corse.', '', 'JARD_2A362_0001', 'MHR_94_JR0001', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-09 16:36:00', '2022-12-21 13:46:35', '41.665336, 9.3626292'),
('Parc de Schoppenwihr', 68630, 'Grand Est', 'Haut-Rhin', '8 Rue de Colmar, 68630 Bennwihr, France', '8 Rue de Colmar, 68630 Bennwihr, France', '8 Rue de Colmar', '', 'Bennwihr', '68026', '68', 44.0, 48.129604000000, 7.3582430000000, '[\"http://www.Schoppenwhir.com\"]', 'Parc paysager,Jardin privé', 2008, 'Un grand parc à l\'Anglaise, ravage pendant la libération de Colmar, Schoppenwihr, est devenu le rendez vous des amoureux de grands arbres. Ces spécimens spectaculaires de taille, d\'essence et de beauté, mettent en valeur un paysage romantique bien compose qui devient d\'autant plus vivant qu\'il n\'y a plus de château pour lui voler la place.', '', 'JARD_68026_0001', 'MHR_44_JR0010', '[]', '[]', '', '2020-06-08 09:24:00', '2022-07-22 10:28:48', '48.129604, 7.358243'),
('Parc de Wesserling', 68470, 'Grand Est', 'Haut-Rhin', '24 Rue du Parc, 68470 Husseren-Wesserling, France', '24 Rue du Parc, 68470 Husseren-Wesserling, France', '24 Rue du Parc', '', 'Husseren-Wesserling', '68089', '68', 44.0, 47.885008700000, 6.9979189000000, '[\"http://www.parc-wesserling.fr/\", \"https://www.instagram.com/parcwesserling/\"]', 'Jardin régulier,Parc paysager,Jardin contemporain,Jardin vivrier,Jardin public', 2006, 'Les cinq jardins remarquables de Wesserling se distinguent par des ambiances variées et un patrimoine arboré de qualité :\r\n - le potager aux motifs textiles, riche en couleurs, arômes et saveurs;\r\n - le jardin régulier, dit \"à la française\", aux formes géométriques;\r\n - les terrasses méditerranéennes exotiques et parfumées;\r\n - le parc \"à l\'anglaise\" mystérieux et romantique;\r\n - le parc rural au calme paisible et au charme discret.', '', 'JARD_68151_0001', 'MHR_44_JR0012', '[]', '[]', 'monument historique', '2020-12-11 13:16:57', '2022-07-22 15:56:35', '47.8850087, 6.9979189'),
('Parc de Flaugergues', 34000, 'Occitanie', 'Hérault', 'Chateau de Flaugergues, 1744 Av. Albert Einstein, 34000 Montpellier, France', 'Chateau de Flaugergues, 1744 Av. Albert Einstein, 34000 Montpellier, France', 'Chateau de Flaugergues', '', 'Montpellier', '34172', '34', 76.0, 43.611077000000, 3.9179910000000, '[\"http://www.flaugergues.com\", \"https://www.facebook.com/chateaudeflaugergues/\", \"https://twitter.com/ChatFlaugergues\", \"https://www.instagram.com/chateau_de_flaugergues/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Construite à la fin du XVIIe siècle, Flaugergues est l\'une de ces demeures appelées \"folies\" édifiées dans la campagne montpelliéraine. Les jardins ont étés aménagés au cours de l\'histoire sur 4 hectares. La présence de la vigne date de l\'époque romaine comme en témoigne la villa romaine au fond du parc (visible sur des photos aériennes).\r\n Les terrasses et le jardin à la française ont été aménagés par Etienne de Flaugergues en 1700. L\'orangerie et le parc à l\'anglaise en 1850 par Charles Joseph de Boussairolles. Une étude des jardins a été faite en 1997 par les étudiants de l\'école d\'architecture de Versailles, afin de redonner un avenir cohérent, ce qui a amené les propriétaires à faire de nombreux réaménagements en particulier, la bambousaie, l\'allée des oliviers, l\'orangerie et ses alentours, ainsi que la création d\'un jardin des sens.', '', 'JARD_34172_0001', 'MHR_76_JR0010', '[]', '[]', 'monument historique', '2020-12-11 13:17:00', '2022-07-22 10:28:06', '43.611077, 3.917991'),
('Jardin d’Emonville', 80100, 'Hauts-de-France', 'Somme', '30 Pl. Clemenceau, 80100 Abbeville, France', '30 Pl. Clemenceau, 80100 Abbeville, France', '30 Pl. Clemenceau', '', 'Abbeville', '80001', '80', 32.0, 50.108508000000, 1.8346770000000, '[\"http://www.abbeville.fr\"]', 'Parc paysager,Jardin public', 2015, 'Le jardin d’Emonville, créé au XIXe siècle, a été façonné par ses anciens propriétaires pour devenir un jardin d’agrément au milieu duquel fut bâti un bel hôtel particulier. Aujourd’hui jardin public labellisé « Jardin remarquable », il propose un jardin anglo-chinois, un arboretum remarquable, ainsi que des massifs de mosaïculture.', '', 'JARD_80001_0001', 'MHR_32_JR0021', '[]', '[]', '', '2020-06-08 09:23:00', '2022-12-20 15:28:21', '50.108508, 1.834677'),
('Parc et jardin du château de Pennautier', 11610, 'Occitanie', 'Aude', '8 Rue Frédéric Mistral, 11610 Pennautier, France', '8 Rue Frédéric Mistral, 11610 Pennautier, France', '8 Rue Frédéric Mistral', '', 'Pennautier', '11279', '11', 76.0, 43.245088000000, 2.3187490000000, '[\"https://www.lorgeril.wine/le-parc/\", \"https://www.facebook.com/LORGERIL/\", \"https://twitter.com/lorgeril\", \"https://www.instagram.com/lorgeril_wines/\"]', 'Jardin régulier,Jardin privé', 2017, 'Remarquable par sa taille et sa situation, il est un magnifique témoin de son temps : \"à la française\" et dessiné par le Nôtre au XVIIe siècle, \"à l’anglaise\" au XIXe siècle, il est aujourd’hui aussi le reflet du temps présent. La partie proche du château est restaurée à la française au XXe siècle. Les souvenirs du parc à l’anglaise sont omniprésents : ruines et rocailles, promenade autour du parc (1.7km), arbres rares, allées de buis, pins et cèdres bicentenaires.', '', 'JARD_11279_0001', 'MHR_76_JR0036', '[\"ouvert\"]', '[\"de jour\"]', '', '', '2022-12-21 11:56:31', '43.245088, 2.318749'),
('Parc zoologique et botanique de Mulhouse Sud Grand-Est', 68100, 'Grand Est', 'Haut-Rhin', '51 Rue du Jardin Zoologique, 68100 Mulhouse, France', '51 Rue du Jardin Zoologique, 68100 Mulhouse, France', '51 Rue du Jardin Zoologique', '', 'Mulhouse', '68224', '68', 44.0, 47.736512000000, 7.3487250000000, '[\"http://www.zoo-mulhouse.com\"]', 'Parc paysager,Jardin de collection,Jardin public', 2006, 'Ensemble paysager de style romantique, le parc, créé en 1867, offre au promeneur des tableaux pittoresques. Il renferme des arbres remarquables et des jardins thématiques d\'iris, rhododendrons, pivoines, hémérocalles, hydrogénas, flore d\'Grand-Est. Le site abrite également un parc zoologique riche de 1200 animaux, qui intègre un programme d\'élevage d\'espèces en voie de disparition.', '', 'JARD_68224_0001', 'MHR_44_JR0014', '[]', '[]', 'vpah', '2020-06-08 09:25:00', '2022-07-22 10:28:08', '47.736512, 7.348725'),
('Jardins de l\'abbaye Notre-Dame', 88700, 'Grand Est', 'Vosges', '2 Rue de l\'Abbaye, 88700 Autrey, France', '2 Rue de l\'Abbaye, 88700 Autrey, France', '2 Rue de l\'Abbaye', '', 'Autrey', '88021', '88', 44.0, 48.295397000000, 6.6900450000000, '[\"http://www.abbayedautrey.com\", \"https://www.facebook.com/abbayedautrey/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2011, 'Replantés à partir de 1982, les jardins de l\'abbaye comprennent un arboretum, un jardin de rocailles parcouru de ruisseaux, un jardin de plantes affectionnant les terrains acides et un jardin de fleurs dédié à la Vierge, remarquable par ses harmonies de teintes.', '', 'JARD_88021_0001', 'MHR_44_JR0044', '[]', '[]', '', '2020-12-11 13:14:42', '2022-07-22 10:27:58', '48.295397, 6.690045'),
('Arboretum du chemin de la découverte', 79500, 'Nouvelle-Aquitaine', 'Deux-Sèvres', '1 Rdpt du Tapis Vert, 79500 Melle, France', '1 Rdpt du Tapis Vert, 79500 Melle, France', '1 Rdpt du Tapis Vert', '', 'Melle', '79174', '79', 75.0, 46.224078000000, -0.1426310000000, '[\"http://www.chemindeladecouverte.fr\"]', 'Jardin contemporain,Jardin de collection,Jardin public', 2006, 'Reconversion originale d’une ancienne voie ferrée, l’arboretum du Chemin de la Découverte présente plusieurs collections remarquables d’arbres, reconnues au niveau national (Tilleuls, Frênes Bouleau, Marronniers, Charme...). La promenade est également ponctuée d\'éléments remarquables comme des lavoirs, un pigeonnier et le \"Jardin d\'eau, Jardin d\'Ortie\" conçu par Gilles Clément.', '', 'JARD_79174_0001', 'MHR_75_JR0046', '[]', '[]', '', '', '2022-07-22 10:28:06', '46.224078, -0.142631'),
('Jardin botanique', 6100, 'Provence-Alpes-Côte d\'Azur', 'Alpes-Maritimes', '31 Parc Maria Séréna Fleurie, 06100 Nice, France', '31 Parc Maria Séréna Fleurie, 06100 Nice, France', '31 Parc Maria Séréna Fleurie', '', 'Nice', '6088', '6', 93.0, 43.733470000000, 7.2446480000000, '[\"https://www.nice.fr/fr/parcs-et-jardins/le-jardin-botanique\"]', 'Jardin de collection,Jardin public', 2009, 'Ouvert au public en 1991, ce jardin est riche de 3500 espèces méditerranéennes issues de différentes régions du monde (collections nationales d’agaves, sauges). Vue panoramique sur la baie des Anges, les Alpes et l’Esterel.', '', 'JARD_06088_0002', 'MHR_93_JR0012', '[]', '[]', '', '2020-12-11 13:16:56', '2022-07-22 10:28:46', '43.73347, 7.244648'),
('Parc paysager Petit Canal', 97131, 'Guadeloupe', 'Guadeloupe', '2 Rue du Parc Paysager, 97131 Petit-Canal,', '2 Rue du Parc Paysager, 97131 Petit-Canal, France', '2 Rue du Parc Paysager', '', 'Petit-Canal', '97119', '971', 1.0, 16.380809000000, -61.4881050000000, '[\"https://www.guadeloupe.fr/activites-sur-terre/parcs-jardins/le-parc-paysager-de-petit-canal/\"]', 'Jardin de collection,Jardin vivrier,Jardin public', 2006, 'Le parc municipal, conçu comme le conservatoire des espèces indigènes de la Grande-Terre, rassemble plus de 300 espèces de la flore locale sur 3 hectares. L\'espace paysager évoque les différents paysages de la zone sèche : savanes, mares, mornes, milieux humides, grotte. Outre la conservation des espèces, le parc poursuit un objectif didactique et culturel. Il possède une case créole, une pépinière, un jardin des plantes médicinales ainsi qu\'une plate-forme des énergies renouvelables. Des journées à thèmes et des animations sont proposées tout au long de l\'année.', '', 'JARD_97119_0001', 'MHR_01_JR0004', '[]', '[]', '', '2020-06-08 09:25:00', '2023-01-08 00:22:18', '16.380809, -61.488105'),
('Jardin du Château', 21610, 'Bourgogne-Franche-Comté', 'Côte-d\'Or', '24 Rue de France, 21610 Fontaine-Française, France', '24 Rue de France, 21610 Fontaine-Française, France', '24 Rue de France', '', 'Fontaine-Française', '21277', '21', 27.0, 47.528159000000, 5.3682960000000, '[\"http://www.chateau-fontainefrancaise.fr\", \"https://www.facebook.com/chfontainefrancaise/\", \"https://www.instagram.com/chateau_fontainefrancaise/\"]', 'Jardin régulier,Jardin privé', 2015, 'Le jardin du XVIIIe siècle est composé de 372 tilleuls taillés en portique, d\'ifs et de buis taillés, avec une vaste pièce d\'eau de 7 hectares.', '', 'JARD_21277_0001', 'MHR_27_JR0007', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-10-11 21:49:30', '47.528159, 5.368296'),
('Jardin de l\'ancienne abbaye de Valsaintes', 4150, 'Provence-Alpes-Côte d\'Azur', 'Alpes-de-Haute-Provence', 'Les Gamattes, 04150 Simiane-la-Rotonde, France', 'Les Gamattes, 04150 Simiane-la-Rotonde, France', 'Les Gamattes', '', 'Simiane-la-Rotonde', '4018', '4', 93.0, 43.974847400000, 5.6009802000000, '[\"http://www.valsaintes.org\", \"https://www.facebook.com/jardinabbayevalsaintes/\", \"https://www.instagram.com/jardin_valsaintes/\"]', 'Jardin contemporain,Jardin privé', 2011, 'Un jardin labellisé « Jardin Remarquable » aux pratiques d\'entretien 100% naturelles (homéopathie, huiles essentielles, insectes auxiliaires...), une église cistercienne du XVIIe siècle, une terre de mémoire depuis la Préhistoire. Flamboyante alliance du minéral et du végétal dont la Rose en est la reine éphémère. Nature, histoire et spiritualité au coeur d\'une Haute-Provence sauvage et préservée pour une balade hors du temps... dans un jardin pas comme les autres !', '', 'JARD_04208_0001', 'MHR_93_JR0003', '[]', '[]', '', '2020-09-15 18:18:00', '2022-10-07 22:39:25', '43.9748474, 5.6009802'),
('Parc du domaine royal de Randan', 63310, 'Auvergne-Rhône-Alpes', 'Puy-de-Dôme', '10 Rue Adélaïde d\'Orléans, 63310 Randan, France', '10 Rue Adélaïde d\'Orléans, 63310 Randan, France', '10 Rue Adélaïde d\'Orléans', '', 'Randan', '63295', '63', 84.0, 46.017097000000, 3.3540020000000, '[\"http://www.domaine-randan.fr\", \"https://www.facebook.com/DomaineRandan/\"]', 'Parc paysager', 2006, 'Les jardins et le parc représentent l\'une des plus importantes créations paysagères de la première moitié du XIXe siècle, conjuguant influences françaises, anglaises et italiennes, perpétuant la tradition du jardin paysager du XVIIIe siècle. Parmi les bâtiments, découvrez la grande orangerie construite vers 1835 et les serres, répliques de celles de Versailles aujourd\'hui disparues. Observez l\'exceptionnelle terrasse formant perspective entre le château et la chapelle : elle conserve son mobilier de jardin d\'origine et offre un panorama sur des paysages préservés. Déambulez à votre guise dans les 40 hectares ouverts à la visite.', '', 'JARD_63295_0001', 'MHR_84_JR0008', '[]', '[]', 'monument historique', '2020-06-08 09:24:00', '2022-10-06 18:40:17', '46.017097, 3.354002'),
('Jardin japonais de Compans-Cafarelli', 31400, 'Occitanie', 'Haute-Garonne', 'Grand Rond, 31400 Toulouse, France', 'Grand Rond, 31400 Toulouse, France', 'Grand Rond', '', 'Toulouse', '31555', '31', 76.0, 43.595622000000, 1.4533440000000, '[\"https://www.parcsetjardins.fr/jardins/794-jardin-japonais-de-compans-caffarelli\"]', 'Jardin contemporain,Jardin public', 2006, 'Ce parc clos de 7 000 m² fait partie d\'un espace vert de 10 hectares en plein cœur du quartier récent de Compans-Caffarelli. Assez rare dans une ville méridionale telle que Toulouse, ce jardin propose des variétés botaniques de l\'extrême-orient. Conçu par le bureau d\'étude du service des jardins et des espaces verts comme un lieu de méditation, on y trouve un jardin minéral, un pont en bois rouge typiquement japonais reliant un îlot qui représente allégoriquement le paradis. Il s\'inspire des jardins créés à Kyoto entre le XIVe siècle et XVIe siècle, correspondant aux époques de Muromachi et d\'Edo. Il est isolé du reste du parc grâce à des rideaux de verdure et une colline offrant une certaine intimité. Le jardin est composé d\'un jardin sec avec une île Grue, une île Tortue et neuf rochers, d\'un lac, d\'un pavillon de thé, et d\'un jardin planté composé d\'une cascade sèche, des pas japonais, une lanternes, un pont rouge, une île du Paradis, un mont Fuji et les pierres des trois saints.', '', 'JARD_31555_0002', 'MHR_76_JR0021', '[]', '[]', '', '', '2022-07-22 10:28:08', '43.595622, 1.453344'),
('Jardins du château de Sauvan', 4300, 'Provence-Alpes-Côte d\'Azur', 'Alpes-de-Haute-Provence', 'Sauvan, 04300 Mane, France', 'Sauvan, 04300 Mane, France', 'Sauvan', '', 'Mane', '4068', '4', 93.0, 43.915975000000, 5.7643290000000, '[\"http://www.chateaudesauvan.com\", \"https://www.facebook.com/chateaudesauvan/\", \"https://twitter.com/chateaudesauvan\", \"https://www.instagram.com/chateaudesauvan/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2005, 'Château d\'un pur style classique du XVIIIe siècle appelé le \"petit Trianon de Provence\" ou \"le palais provençal de la dernière amie de la reine Marie-Antoinette\".\r\nArbres bicentenaires, pièces d\'eau,statues ,vases, volières, animaux en liberté (cygnes,paons).', '', 'JARD_04111_0001', 'MHR_93_JR0002', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-10-07 19:06:36', '43.915975, 5.764329'),
('Parc du château de Montmarin', 35730, 'Bretagne', 'Ille-et-Vilaine', '8 Chem. du Four, 35730 Pleurtuit, France', '8 Chem. du Four, 35730 Pleurtuit, France', '8 Chem. du Four', '', 'Pleurtuit', '35228', '35', 53.0, 48.595932000000, -2.0741680000000, '[\"http://www.domaine-du-montmarin.com\", \"https://www.facebook.com/DomaineduMontmarin\", \"https://www.instagram.com/domainedumontmarin/\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2005, 'Un jardin classique est établi en 1762 sur les quatre terrasses en bordure de Rance d’une demeure de plaisance construite à cette époque par un armateur malouin. Deux d’entre elles sont conservées et restaurées en 1885, le reste du jardin étant alors réaménagé en parc romantique par un probable collaborateur des frères Bühler. Cet ensemble est complété par une rocaille en 1920 (MH – 6 ha).', '', 'JARD_35228_0001', 'MHR_53_JR0021', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:00', '48.595932, -2.074168'),
('Parc du château des Ravalet', 50110, 'Normandie', 'Manche', '2 Rue du Général de Gaulle, 50110 Cherbourg-en-Cotentin, France', '2 Rue du Général de Gaulle, 50110 Cherbourg-en-Cotentin, France', '2 Rue du Général de Gaulle', '', 'Cherbourg-en-Cotentin', '50129', '50', 28.0, 49.639333000000, -1.5694160000000, '[\"http://www.ville-cherbourg.fr\"]', 'Jardin régulier,Parc paysager,Jardin public', 2004, 'Le château est situé dans un superbe parc paysager de 14 hectares, aux sentiers sinueux et aux arbres remarquables. Le parc abrite également un conservatoire du dahlia, et offre une vaste prairie bordée d\'espaces naturels.', '', 'JARD_50129_0001', 'MHR_28_JR0014', '[]', '[]', 'monument historique', '2020-09-15 18:16:00', '2022-07-22 10:28:16', '49.639333, -1.569416'),
('Jardin Germaine L\'Hardy-Denonain', 83580, 'Provence-Alpes-Côte d\'Azur', 'Var', '7 Rue de la Tasco, 83580 Gassin, France', '7 Rue de la Tasco, 83580 Gassin, France', '7 Rue de la Tasco', '', 'Gassin', '83065', '83', 93.0, 43.228845000000, 6.5856850000000, '[\"https://gassin.eu/fr/loisirs/parc-et-jardin/gassin/jardin-botanique-remarquable-l-hardy-denonain-4681136/\"]', 'Jardin de collection,Jardin privé', 2009, 'Le jardin a été remis en état par l\'artiste peintre Germaine L\'Hardy-Denonain entre 1974 et 1984.\r\n Quatre restanques plantées de 500 espèces méditerranéennes, bassin, plantes aquatiques, médicinales, tinctoriales. Plus de 600 espèces et variétés étiquetées.', '', 'JARD_83065_0001', 'MHR_93_JR0024', '[]', '[]', '', '2020-06-08 09:23:00', '2022-07-22 10:28:10', '43.228845, 6.585685'),
('Jardin de la rue au Lin', 22570, 'Bretagne', 'Côtes d\'Armor', '16 Rue au Lin, 22570 Gouarec, France', '16 Rue au Lin, 22570 Gouarec, France', '16 Rue au Lin', '', 'Gouarec', '22064', '22', 53.0, 48.225575000000, -3.1786990000000, '[\"http://www.jardinenville-gouarec.fr/\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2020, 'Jardin urbain d’inspiration anglaise, créé en 1993 dans une propriété familiale en bordure de rivière, avec le concours du paysagiste Michel Gesret. Plusieurs espaces, délimités par des structures végétales (haies, banquettes, massifs…) ou minérales (schiste, granite), forment un ensemble élégant et subtil, d’une belle diversité de couleurs et d’ambiances malgré ses dimensions réduites (0,8 ha).', '', 'JARD_22064_0001', 'MHR_53_JR0024', '[\"ouvert\"]', '[\"saisonnière\", \"de jour\"]', '', '', '2022-12-16 16:15:56', '48.225575, -3.178699'),
('Jardin de l\'évêché', 81100, 'Occitanie', 'Tarn', '26 Rue de l\'Hôtel de ville, 81100 Castres, France', '26 Rue de l\'Hôtel de ville, 81100 Castres, France', '26 Rue de l\'Hôtel de ville', '', 'Castres', '81065', '81', 76.0, 43.604867000000, 2.2397880000000, '[\"http://www.ville-castres.fr\"]', 'Jardin régulier,Jardin public', 2004, 'La ville de Castres a conservé dans son intégralité ce jardin du XVIIe siècle dessiné par A. Le Nôtre, ce qui lui donne une très grande valeur historique. Les irrégularités du terrain de forme trapézoïdale, bordé par l\'Agout, ont été maîtrisées par le Nôtre en déviant sa composition vers la droite pour lui donner plus de profondeur. C\'est un exemple rare de parterre de broderie à quatre compartiments aux arabesques de buis se terminant par des enroulements soutenus et couronnés de palmes et volutes.', '', 'JARD_81065_0001', 'MHR_76_JR0029', '[]', '[]', 'monument historique; vpah', '', '2022-07-22 10:28:18', '43.604867, 2.239788'),
('Jardin du château de Saint-Bernard', 1600, 'Auvergne-Rhône-Alpes', 'Ain', '152 Av. Suzanne Valadon, 01600 Saint-Bernard, France', '152 Av. Suzanne Valadon, 01600 Saint-Bernard, France', '152 Av. Suzanne Valadon', '', 'Saint-Bernard', '1339', '1', 84.0, 45.944778000000, 4.7324750000000, '[\"https://www.chateaudesaintbernard.com/visiter\"]', 'Jardin régulier,Jardin contemporain,Jardin privé', 2011, 'Jardin privé de 2 hectares créé en 2003, situé dans le cadre d\'un château XVIIe et XIXe siècles. Jardin régulier constitué de carrés thématiques, labyrinthe de 600 pommiers et poiriers, roseraie.', '', 'JARD_01339_0001', 'MHR_84_JR0010', '[\"ouvert\"]', '[\"de jour\"]', '', '2020-06-09 09:16:00', '2022-12-15 16:46:29', '45.944778, 4.732475'),
('Parc et jardin du château de Margon', 34320, 'Occitanie', 'Hérault', '1 Rue des Banastes, 34320 Margon, France', '1 Rue des Banastes, 34320 Margon, France', '1 Rue des Banastes', '', 'Margon', '34149', '34', 76.0, 43.486332000000, 3.3057670000000, '[\"http://chateaudemargon.com\", \"https://www.facebook.com/chateaudemargon\", \"https://www.instagram.com/chateau_de_margon/\"]', 'Jardin régulier,Jardin privé', 2004, 'Ce sont des jardins réguliers de composition classique à la française avec le côté structuré du jardin à l’italienne. On y trouve des cyprès en colonne, des topiaires en lauriers sauce, des allées bordées de lauriers roses, des grenadiers à fruit ou à fleur, des oliviers taillés en tambour et une collection d’iris.', '', 'JARD_34149_0001', 'MHR_76_JR0013', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:06', '43.486332, 3.305767'),
('Jardin des Serres d\'Auteuil', 75016, 'Île-de-France', 'Paris', '3 Av. de la Prte d\'Auteuil, 75016 Paris, France', '3 Avenue de la Porte d\'Auteuil, 75016 Paris, France', '3 Avenue de la Porte d\'Auteuil', '', 'Paris', '75056', '75', 11.0, 48.847807700000, 2.2523233000000, '[\"https://www.paris.fr/lieux/jardin-des-serres-d-auteuil-1780\"]', 'Jardin de collection,Jardin public', 2021, 'Le jardin des Serres d \'Auteuil fait partie, avec le parc de Bagatelle , le Parc Floral et l\'Arboretum, du Jardin Botanique de Paris. Le patrimoine naturel est mis en valeur grâce à une mise en scène des collections et une signalétique commune aux 4 sites. Dans les serres d’Auteuil, des collections bénéficient d\'une scénographie paysagère. C’est le cas des orchidées, des fougères, des bégonias, des broméliacées, et des ficus (entrée par le palmarium). Une serre sera affectée à une collection récente : les palmiers endémiques et ethnobotaniques.', '', '', '', '[\"ouvert\"]', '[\"à l’année\", \"de jour\"]', '', '2022-09-15 12:43:12', '2022-12-19 18:17:48', '48.8478077, 2.2523233'),
('Jardin du château de La Muette', 2600, 'Hauts-de-France', 'Aisne', '7 Rue du Château, 02600 Largny-sur-Automne, France', '7 Rue du Château, 02600 Largny-sur-Automne, France', '7 Rue du Château', '', 'Largny-sur-Automne', '2410', '2', 32.0, 49.260525000000, 3.0363600000000, '[\"http://www.jardinsdelamuette.com\"]', 'Jardin régulier,Jardin privé', 2004, 'Aménagés le long des vestiges d\'une terrasse du XVIe siècle, les jardins de la Muette se déploient sur 3 hectares et proposent allées de marronniers, de tilleuls, jardin de buis, cour des hydrangeas, grande terrasse dominant la vallée de l\'Automne.', '', 'JARD_02410_0001', 'MHR_32_JR0010', '[]', '[]', 'monument historique', '2020-09-15 18:16:00', '2022-07-22 10:28:14', '49.260525, 3.03636'),
('Jardins de Monperthuis', 61360, 'Normandie', 'Orne', 'La Pillardière, 61360 Chemilli, France', 'La Pillardière, 61360 Chemilli, France', 'La Pillardière', '', 'Chemilli', '61037', '61', 28.0, 48.356534000000, 0.4301910000000, '[\"http://www.lesjardinsdumontperthuis.com\"]', 'Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2021, 'Jardins conçus en 2010 par le paysagiste Philippe Dubreuil autour d\'un ensemble typiquement percheron en cours de restauration, constitué d\'un manoir du XVe-XVIe siècle, de sa longère, sa grange seigneuriale, écuries et porcheries, fournil, four à chanvre et puits couvert. Ce jardin s\'articule en fonction des bâtiments et de leurs usages, jardin potager et verger conservatoire de pommiers anciens percherons à cidre et à couteau près des communs, jardin de simples près du manoir, broderie d\'osmanthes et de graminées, collection de cerisiers d\'ornement, de chênes, de tilleuls, d\'aubépines, de pivoines, d\'hydrangeas. Roseraie de plus de 300 variétés de roses anciennes. Serre avec collection de cactées et d\'agrumes. Entouré de champs et bordé d\'une rivière et de bois, le jardin reprends les thèmes et les grandes lignes de l\'histoire des jardins.', '', '', '', '[]', '[]', '', '2022-09-14 17:59:57', '2022-09-14 17:59:57', '48.356534, 0.430191'),
('Jardin aquatique Acorus', 70700, 'Bourgogne-Franche-Comté', 'Haute-Saône', '13 Rue des Corvées, 70700 Autoreille, France', '13 Rue des Corvées, 70700 Autoreille, France', '13 Rue des Corvées', '', 'Autoreille', '70039', '70', 27.0, 47.368498000000, 5.8073660000000, '[\"http://jardin-aquatique-acorus.fr\", \"https://www.facebook.com/Jardin.Aquatique.Acorus\"]', 'Parc paysager,Jardin contemporain,Jardin privé', 2015, 'Le jardin \"Acorus\" commencé en 1992 a pour vocation de présenter le milieu aquatique et de faire découvrir un écosystème spécifique. Il se situe dans un vallon perché au-dessus du village, en lisière de forêt. Entre jardin à l’anglaise et jardin japonais, on y découvre différents types de pièces d’eau, bassins de lotus, de nénuphars, baignade biologique, cascades, étangs bucoliques.', '', 'JARD_70039_0001', 'MHR_27_JR0030', '[]', '[]', '', '2020-12-11 13:15:37', '2022-07-22 10:27:53', '47.368498, 5.807366'),
('Jardins du Pays d\'Auge', 14340, 'Normandie', 'Calvados', 'Avenue des Tilleuls, 14340 Cambremer, France', 'Avenue des Tilleuls, 14340 Cambremer, France', 'Avenue des Tilleuls', '', 'Cambremer', '14033', '14', 28.0, 49.146864000000, 0.0456050000000, '[\"http://www.lesjardinsdupaysdauge.com\"]', 'Parc paysager,Jardin contemporain,Jardin vivrier,Jardin privé', 2021, 'Des jardins à thème entourent une ferme du XVIIe siècle. La chapelle et ses trois oratoires. Les bâtiments à pans de bois ponctuant les jardins à thèmes, le cloître, chambre symbolique orné en son centre d\'une fontaine, les salons de jardin, les statues.', '', '', '', '[]', '[]', '', '2022-09-14 17:41:29', '2022-09-14 17:45:32', '49.146864, 0.045605');
INSERT INTO `liste_des_jardins_remarquables` (`Nom du jardin`, `Code Postal`, `Region`, `Departement`, `Adresse complete`, `Adresse de l’entree du public`, `Numero et libelle de la voie`, `Complement d'adresse`, `Commune`, `Code INSEE`, `Code INSEE Departement`, `Code INSEE Region`, `Latitude`, `Longitude`, `Site Internet et autres liens`, `Types`, `Annee d'obtention`, `Description`, `Auteur / Nom de l'illustre`, `Identifiant DEPS`, `Identifiant origine`, `Accessible au public`, `Conditions d’ouverture`, `Equipement Précision`, `Date de création`, `Date de MAJ`, `coordonnees_geographiques`) VALUES
('Parc et jardins du château du Lude', 72800, 'Pays de la Loire', 'Sarthe', '2 Pl. François de Nicolay, 72800 Le Lude, France', '2 Pl. François de Nicolay, 72800 Le Lude, France', '2 Pl. François de Nicolay', '', 'Le Lude', '72176', '72', 52.0, 47.646950000000, 0.1566200000000, '[\"http://www.lelude.com\", \"https://www.facebook.com/chateaudulude\", \"https://www.instagram.com/chateaudulude/\", \"https://www.youtube.com/channel/UCZa4XPr_DE37ogRde4q3AiA\"]', 'Jardin régulier,Parc paysager,Jardin privé', 2004, 'Une longue terrasse domine, depuis la Renaissance, le jardins bas, le parc agricole, aux bouquets d\'arbres centenaires, puis les jardins réguliers, dessinés par Édouard André en 1880. On lui doit aussi le jardin romantique de la Source et le potager avec les serres et l\'orangerie, toujours en usage aujourd\'hui. A voir également, serti dans les murailles médiévales, le Jardin de l’Éperon intégrant une collection de roses dont les roses-thé chinoises et un labyrinthe de buis.', '', 'JARD_72176_0001', 'MHR_52_JR0013', '[]', '[]', 'monument historique', '2020-06-08 09:25:00', '2022-07-22 10:28:12', '47.64695, 0.15662'),
('Jardin d\'eau de l’Aubepré', 54115, 'Grand Est', 'Meurthe-et-Moselle', '3 Rue Saint-Florentin, 54115 Gélaucourt, France', '3 Rue Saint-Florentin, 54115 Gélaucourt, France', '3 Rue Saint-Florentin', '', 'Gélaucourt', '54218', '54', 44.0, 48.454498000000, 5.9897150000000, '[\"https://www.parcsetjardins.fr/jardins/1441-jardin-d-eau-de-l-aubepre\"]', 'Jardin contemporain,Jardin de collection,Jardin public', 2011, 'Le jardin d\'eau de 8000 m2 constitue un patrimoine paysager unique, labellisé Jardin Remarquable. Créé en 1999 par Michel Capdevielle, Lionel Gonzalez et Raphaël Arnoult, il offre une large variété d\'arbres, arbustes, vivaces et essences botaniques intégrée dans un environnement végétal naturel et regroupe une estimable collection de plantes de milieux humides habilement mise en scène.', '', 'JARD_54218_0001', 'MHR_44_JR0034', '[]', '[]', '', '2020-12-11 13:16:57', '2022-07-22 10:27:57', '48.454498, 5.989715'),
('Parc et jardin du château de Bournel', 25680, 'Bourgogne-Franche-Comté', 'Doubs', 'Domaine de Bournel Route du Château de Bournel, 25680 Cubry, France', 'Domaine de Bournel Route du Château de Bournel, 25680 Cubry, France', 'Domaine de Bournel Route du Château de Bournel', '', 'Cubry', '25182', '25', 27.0, 47.487153000000, 6.4148180000000, '[\"http://www.bournel.com\"]', 'Jardin régulier,Parc paysager,Jardin vivrier,Jardin privé', 2011, 'Dans un immense parc aux essences rares (fin du XIXe siècle), s’inscrit sur 7 hectares, la terrasse du château où prennent place un jardin régulier à la française délimité par des allées de buis, une grande charmille et un jardin potager qui a gardé toute ses structures essentielles : bassins, allées couvertes d’arbres fruitiers en espalier, gloriettes, grotte et serre. Collection de pivoines et roses anciennes.', '', 'JARD_25182_0001', 'MHR_27_JR0017', '[]', '[]', 'monument historique', '', '2022-07-22 10:28:17', '47.487153, 6.414818'),
('Jardins de la Pellerine', 53220, 'Pays de la Loire', 'Mayenne', 'La Larderie, 53220 La Pellerine', 'La Larderie, 53220 La Pellerine, France', 'La Larderie', '', 'La Pellerine', '53126', '53', 52.0, 48.317527942799, -1.0410157883536, '[\"http://lejardindelapellerine.simplesite.com/\"]', 'Parc paysager,Jardin contemporain,Jardin de collection,Jardin privé', 2004, 'Jardin intimiste et exubérant, composé d’une succession de chambres de verdure qui accueillent un foisonnement de plantes vivaces, rosiers anciens et arbustes rares.', '', 'JARD_53177_0001', 'MHR_52_JR0007', '[\"ouvert\"]', '[\"saisonnière\", \"de jour\"]', '', '', '2022-12-16 16:47:29', '48.317527942799, -1.0410157883536'),
('Jardins du prieuré de Laverré', 86340, 'Nouvelle-Aquitaine', 'Vienne', '15 Rte du Prieure, 86340 Aslonnes, France', '15 Rte du Prieure, 86340 Aslonnes, France', '15 Rte du Prieure', '', 'Aslonnes', '86010', '86', 75.0, 46.469469000000, 0.3156170000000, '[]', 'Jardin régulier,Jardin contemporain,Jardin vivrier,Jardin privé', 2004, 'Ce jardin, constitué de plantes anciennes et de buis, est traité à la façon du XVIIe siècle avec la sobriété des jardins des moines. Les douves en eau et les ruisseaux contribuent au charme des lieux. La visite se poursuit dans la roseraie plantée de roses anciennes ou très rares.', '', 'JARD_86010_0001', 'MHR_75_JR0004', '[]', '[]', 'monument historique', '2020-06-08 09:23:00', '2022-07-22 10:28:03', '46.469469, 0.315617'),
('Jardin du Temps', 68110, 'Grand Est', 'Haut-Rhin', '81 Rue des Vosges, 68110 Illzach, France', '81 Rue des Vosges, 68110 Illzach, France', '81 Rue des Vosges', '', 'Illzach', '68154', '68', 44.0, 47.779278000000, 7.3580470000000, '[\"http://www.jardins-du-temps.fr/\"]', 'Jardin contemporain,Jardin privé', 2012, 'Jardins créés en 2005, sur 2 hectares. Dans nos jardins se succèdent différentes scènes telles les \"paysages aquatiques\" et \"la forêt enchantée\". L’originalité de ce jardin réside dans son caractère naturaliste : agencement en masse de vivaces et de graminées à caractère sauvage. Œuvres artistiques et anachroniques, cabanes originales et sentier pieds nus participent à la magie des lieux.', '', 'JARD_68154_0001', 'MHR_44_JR0013', '[]', '[]', '', '2020-12-11 13:16:28', '2022-10-07 22:19:21', '47.779278, 7.358047'),
('Domaine d\'Orvès', 83160, 'Provence-Alpes-Côte d\'Azur', 'Var', 'Remarquable du Domaine d\'Orvès Garden, 71 Av. de la Libération, 83160 La Valette-du-Var, France', 'Remarquable du Domaine d\'Orvès Garden, 71 Av. de la Libération, 83160 La Valette-du-Var, France', 'Remarquable du Domaine d\'Orvès Garden', '', 'La Valette-du-Var', '83144', '83', 93.0, 43.143966746803, 5.9895863480864, '[\"http://www.domainedorves.fr\"]', 'Jardin régulier,Jardin privé', 2005, 'Jardin \"à la française\" et parc \"à l’anglaise\" sur 8 hectares. Bastide provençale fin XVIIe siècle Statuaire, chapelle, plan d’eau.', '', 'JARD_83144_0001', 'MHR_93_JR0033', '[]', '[]', 'monument historique', 'import', '2020-06-08 09:24:00', '43.143966746803, 5.9895863480864'),
('Jardin Jacques Prévert', 50440, 'Normandie', 'Manche', '2 La Vallée, 50440 La Hague, France', '2 La Vallée, 50440 La Hague, France', '2 La Vallée', '', 'La Hague', '50041', '50', 28.0, 49.708391000000, -1.8999990000000, '[\"https://www.parcsetjardins.fr/jardins/88-jardins-en-hommage-a-jacques-prevert\"]', 'Jardin privé', 2004, 'Jardin naturel, rivière. Poèmes de Jacques Prévert. sculptures modernes', '', 'JARD_50041_0003', 'MHR_28_JR0012', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:28:16', '49.708391, -1.899999'),
('Le Bois Marquis', 38150, 'Auvergne-Rhône-Alpes', 'Isère', '7 Rue des Contancines, 38150 Vernioz, France', '7 Rue des Contancines, 38150 Vernioz, France', '7 Rue des Contancines', '', 'Vernioz', '38536', '38', 84.0, 45.428315000000, 4.8803400000000, '[\"http://www.lejardinduboismarquis.com\"]', 'Parc paysager,Jardin contemporain,Jardin de collection,Jardin privé', 2011, 'Jardin privé de 5,5 hectares créé en 1980, à tonalité anglaise, arboretum (hêtres de Dawyck, érables à peau de serpent, bouleaux et prunus serrula, chênes, érables japonais...) et massifs privilégiant les écorces et feuillages vifs ou spectaculaires. Deux étangs abritent des canards d\'ornement. Ouvert toute l\'année et sur RV pour les VG.', '', 'JARD_38536_0001', 'MHR_84_JR0026', '[]', '[]', '', '2020-06-08 09:25:00', '2022-07-22 10:27:55', '45.428315, 4.88034');
